cd /work; cat > tests/interpreter.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

const r = (pts: number[]) => pts.map((v) => Math.round(v * 1e6) / 1e6 + 0);

describe("run: basic 2D drawing", () => {
  test("kwadrat draws four 120-unit sides clockwise from origin heading +Y", () => {
    const { segments, error } = run("powtorz 4 [\n  np 120\n  pw 90\n]", "2d");
    expect(error).toBeNull();
    expect(segments.map((s) => [r(s.from), r(s.to)])).toEqual([
      [[0, 0, 0], [0, 120, 0]],
      [[0, 120, 0], [120, 120, 0]],
      [[120, 120, 0], [120, 0, 0]],
      [[120, 0, 0], [0, 0, 0]],
    ]);
    expect(segments[0].color).toBe("#16866a");
    expect(segments[0].width).toBe(3);
  });
});
EOF
