cd /work/src/lang; cat > lexer.ts <<'EOF'
export type TokType = "word" | "number" | "string" | "op" | "cmp" | "[" | "]" | "(" | ")" | ",";

export interface Token {
  type: TokType;
  text: string;
  line: number;
  col: number;
  /** whitespace (or start of input) immediately before / after */
  spaceBefore: boolean;
  spaceAfter: boolean;
  /** first token on its line */
  lineStart: boolean;
  /** last token on its line */
  lineEnd: boolean;
}

export class LogoError extends Error {
  constructor(message: string, public line: number, public column: number) {
    super(message);
  }
}

const WORD_START = /[\p{L}_:]/u;
const WORD_CHAR = /[\p{L}\p{N}_.:]/u;

export function tokenize(src: string): Token[] {
  const toks: Token[] = [];
  let i = 0, line = 1, col = 1;
  let lineHasTok = false;
  const adv = () => {
    if (src[i] === "\n") { line++; col = 1; lineHasTok = false; } else col++;
    i++;
  };
  while (i < src.length) {
    const c = src[i];
    if (c === "\n" || c === " " || c === "\t" || c === "\r" || c === "\f" || c === "\v" || c === " ") { adv(); continue; }
    if (c === ";") { while (i < src.length && src[i] !== "\n") adv(); continue; }
    const startLine = line, startCol = col, start = i;
    let type: TokType;
    if (/[0-9.]/.test(c)) {
      while (i < src.length && /[0-9]/.test(src[i])) adv();
      if (src[i] === ".") { adv(); while (i < src.length && /[0-9]/.test(src[i])) adv(); }
      const text = src.slice(start, i);
      if (text === "." || (i < src.length && WORD_CHAR.test(src[i]))) {
        while (i < src.length && WORD_CHAR.test(src[i])) adv();
        throw new LogoError(`Niepoprawna liczba „${src.slice(start, i)}”.`, startLine, startCol);
      }
      type = "number";
    } else if (WORD_START.test(c)) {
      while (i < src.length && WORD_CHAR.test(src[i])) adv();
      type = "word";
    } else if (c === '"') {
      adv();
      while (i < src.length && /[^\s\[\]()]/.test(src[i])) adv();
      type = "string";
    } else if ("+-*/".includes(c)) { adv(); type = "op"; }
    else if (c === "<" || c === ">" || c === "=") {
      adv();
      if (c === "<" && (src[i] === "=" || src[i] === ">")) adv();
      else if (c === ">" && src[i] === "=") adv();
      type = "cmp";
    } else if ("[]()".includes(c)) { adv(); type = c as TokType; }
    else if (c === ",") { adv(); type = ","; }
    else throw new LogoError(`Nieznany znak „${c}”.`, startLine, startCol);
    const prev = toks[toks.length - 1];
    const spaceBefore = start === 0 || /\s/.test(src[start - 1]) || src[start - 1] === undefined;
    toks.push({ type, text: src.slice(start, i), line: startLine, col: startCol, spaceBefore, spaceAfter: true, lineStart: !lineHasTok, lineEnd: true });
    if (prev && prev.line === startLine) prev.lineEnd = false;
    lineHasTok = true;
  }
  for (let k = 0; k < toks.length; k++) {
    const t = toks[k], n = toks[k + 1];
    // whitespace after = next token not adjacent
    t.spaceAfter = !n || n.spaceBefore || n.line !== t.line;
  }
  return toks;
}
EOF
echo ok

