cd /work/src/lang; cat > ast.ts <<'EOF'
import type { Token } from "./lexer";

export type Expr =
  | { kind: "num"; value: number; tok: Token }
  | { kind: "var"; name: string; tok: Token }
  | { kind: "repcount"; depth: number; tok: Token }
  | { kind: "neg"; arg: Expr; tok: Token }
  | { kind: "bin"; op: string; left: Expr; right: Expr; tok: Token };

export interface Cond { left: Expr; op: string; right: Expr; tok: Token }

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: "pitch"; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: "roll"; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: "pen"; down: boolean; tok: Token }
  | { kind: "color"; color: string; tok: Token }
  | { kind: "width"; arg: Expr; tok: Token }
  | { kind: "repeat"; count: Expr; body: Stmt[]; tok: Token; end: Token }
  | { kind: "let"; name: string; arg: Expr; tok: Token }
  | { kind: "if"; cond: Cond; then: Stmt[]; else: Stmt[] | null; tok: Token }
  | { kind: "stop"; tok: Token }
