const dist = (src: string, mode: "2d" | "3d" = "2d") => {
  const { segments, error } = run(src, mode);
  if (error) return error;
  return Math.round(segments.reduce((a, s) => a + Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]), 0) * 1e6) / 1e6;
};

describe("run: expressions", () => {
  test("precedence and left associativity", () => {
    expect(dist("np 20 - 5 - 3")).toBe(12);
    expect(dist("np 2 + 3 * 4")).toBe(14);
    expect(dist("np 100 / 5 / 2")).toBe(10);
    expect(dist("np (2 + 3) * 4")).toBe(20);
  });
  test("operator spacing: both sides or neither", () => {
    expect(dist("np 10 - 5")).toBe(5);
    expect(dist("np 10-5")).toBe(5);
    expect(dist("np 2*3+1")).toBe(7);
    const e = run("np 10 -5", "2d").error;
    expect(e).toMatchObject({ line: 1, column: 7 });
  });
  test("stacked unary signs", () => {
    expect(run("np -(3 - 5)", "2d").segments[0].to[1]).toBe(2);
    expect(run("np - -2", "2d").segments[0].to[1]).toBe(2);
    expect(run("np +-2", "2d").segments[0].to[1]).toBe(-2);
  });
  test("numbers: decimals ok, exotic forms are errors", () => {
    expect(dist("np .5")).toBe(0.5);
    expect(dist("np 12.5")).toBe(12.5);
    for (const bad of ["np 1e3", "np 0x10", "np NaN", "np Infinity"]) expect(run(bad, "2d").error).not.toBeNull();
  });
  test("division by zero is a run-time error at the argument, keeping earlier strokes", () => {
    const res = run("np 10\nnp 5 / (2 - 2)", "2d");
    expect(res.segments.length).toBe(1);
    expect(res.error).toMatchObject({ line: 2, column: 4 });
  });
});
