cd /work; cat >> tests/interpreter.test.ts <<'EOF'

describe("run: pen state and turtle commands", () => {
  test("pen up moves without drawing; Polish and English aliases are equivalent", () => {
    const a = run("pod np 10 opu np 10 PU fd 5 pd forward 5", "2d");
    expect(a.error).toBeNull();
    expect(a.segments.map((s) => [s.from[1], s.to[1]])).toEqual([[10, 20], [25, 30]]);
    expect(run("podnieś naprzód 3 opuść wstecz 3", "2d").segments.length).toBe(1);
  });
  test("colour literal is lower-cased; width applies to later strokes", () => {
    const { segments } = run('kolor "#ABCDEF" grubość 7 np 10 color "#000000" width 1 np 1', "2d");
    expect(segments.map((s) => [s.color, s.width])).toEqual([["#abcdef", 7], ["#000000", 1]]);
  });
  test("malformed colour is a parse-time error at the colour", () => {
    expect(run('np 10 kolor "#12345"', "2d")).toEqual({ segments: [], error: expect.objectContaining({ line: 1, column: 13 }) });
    expect(run("kolor 5", "2d").error).toMatchObject({ column: 7 });
  });
  test("literal width out of range or fractional is a parse-time error at the argument", () => {
    expect(run("np 5 grubosc 13", "2d")).toEqual({ segments: [], error: expect.objectContaining({ column: 14 }) });
    expect(run("grubosc 2.5", "2d").error).toMatchObject({ column: 9 });
    expect(run("grubosc 0", "2d").error).not.toBeNull();
    expect(run("grubosc 12 np 1", "2d").error).toBeNull();
  });
  test("literal repeat count out of range is a parse-time error", () => {
    expect(run("powtorz 10001 [np 1]", "2d").error).toMatchObject({ column: 9 });
    expect(run("powtorz 1.5 [np 1]", "2d").error).toMatchObject({ column: 9 });
    expect(run("powtorz 0 [np 1]", "2d")).toEqual({ segments: [], error: null });
  });
  test("dom returns to origin drawing a segment and resets orientation only", () => {
    const { segments } = run('pw 90 np 10 kolor "#ff0000" dom np 5', "2d");
    expect(segments.map((s) => [r(s.from), r(s.to), s.color])).toEqual([
      [[0, 0, 0], [10, 0, 0], "#16866a"],
      [[10, 0, 0], [0, 0, 0], "#ff0000"],
      [[0, 0, 0], [0, 5, 0], "#ff0000"],
    ]);
    expect(run("dom", "2d").segments).toEqual([]);
  });
  test("czyść forgets earlier segments but keeps the turtle", () => {
    const { segments } = run("np 10 czysc np 5", "2d");
    expect(segments.map((s) => [s.from[1], s.to[1]])).toEqual([[10, 15]]);
  });
  test("stop at top level ends the program", () => {
    expect(run("np 1 stop np 2", "2d").segments.length).toBe(1);
    expect(run("powtorz 5 [np 1 stop]", "2d").segments.length).toBe(1);
  });
  test("a zero move draws nothing", () => {
    expect(run("np 0", "2d").segments).toEqual([]);
  });
  test("unknown command and missing argument positions", () => {
    expect(run("np 1\n  skacz 4", "2d").error).toMatchObject({ line: 2, column: 3 });
    expect(run("powtorz 2 [np]", "2d").error).toMatchObject({ column: 14 });
    expect(run("np 4\nnp", "2d").error).toMatchObject({ line: 2, column: 1 });
    expect(run("np 4 5", "2d").error).toMatchObject({ column: 6 });
  });
});
EOF
