cd /work; cat >> tests/interpreter.test.ts <<'EOF'

describe("run: variables and nrpowt", () => {
  test("niech assigns and reassigns; legacy :name works; names ignore case", () => {
    expect(dist("niech bok 10 np bok niech bok bok * 2 np :BOK")).toBe(30);
  });
  test("a top-level variable may be used before its niech appears in the text", () => {
    const res = run("powtorz 2 [jeśli nrpowt = 2 [np x] niech x 7]", "2d");
    expect(res).toEqual({ segments: [expect.objectContaining({ to: [0, 7, 0] })], error: null });
  });
  test("reading a declared but unassigned variable is a run-time error at the argument", () => {
    const res = run("np 5\nnp 2 * x\nniech x 1", "2d");
    expect(res.segments.length).toBe(1);
    expect(res.error).toMatchObject({ line: 2, column: 4 });
  });
  test("undeclared name is a parse-time error at the name", () => {
    expect(run("np 5 np 3 + y", "2d")).toEqual({ segments: [], error: expect.objectContaining({ column: 13 }) });
  });
  test("variables cannot be named after commands", () => {
    expect(run("niech np 4", "2d").error).toMatchObject({ column: 7 });
  });
  test("nrpowt counts iterations of the innermost repeat from 1", () => {
    const { segments } = run("powtorz 2 [powtorz 3 [np nrpowt]]", "2d");
    expect(segments.map((s) => Math.round(s.to[1] - s.from[1]))).toEqual([1, 2, 3, 1, 2, 3]);
    expect(run("np repcount", "2d").error).toMatchObject({ column: 4 });
  });
  test("width and repeat count computed from names are checked at run time", () => {
    const res = run("niech g 20\nnp 1\ngrubosc g", "2d");
    expect(res.segments.length).toBe(1);
    expect(res.error).toMatchObject({ line: 3, column: 9 });
    expect(run("niech n -1 np 1 powtorz n [np 1]", "2d").error).toMatchObject({ column: 26 });
  });
});
EOF
