describe("run: procedures", () => {
  const square = "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n";
  test("brief example: kwadrat 80 90 draws an 80-unit square", () => {
    const { segments, error } = run(square + "\nkwadrat 80 90", "2d");
    expect(error).toBeNull();
    expect(segments.map((s) => r(s.to))).toEqual([[0, 80, 0], [80, 80, 0], [80, 0, 0], [0, 0, 0]]);
  });
  test("arguments are expressions; calls may precede the definition; legacy header", () => {
    const src = "kw 40 * 2 90\nto KW :bok :kąt\n  repeat 4 [fd :bok rt kąt]\nend";
    expect(dist(src)).toBe(320);
  });
  test("a parameter may share its name with a procedure", () => {
    expect(dist("oto a ma: a\n np a\njuż\na 7")).toBe(7);
  });
  test("recursion with stop inside a conditional ends only the current call", () => {
    const src = "oto s ma: n\n jeśli n = 0 [stop]\n np n\n s n - 1\n np 100\njuż\ns 3";
    expect(dist(src)).toBe(3 + 2 + 1 + 300);
  });
  test("niech in a procedure is local and shadows the global only after it runs", () => {
    const src = "niech x 5\noto p\n np x\n niech x 1\n np x\njuż\np\nnp x";
    expect(run(src, "2d").segments.map((s) => Math.round(s.to[1] - s.from[1]))).toEqual([5, 1, 5]);
  });
  test("a procedure-local variable is not visible at top level", () => {
    expect(run("oto p\n niech y 1\njuż\nnp y", "2d").error).toMatchObject({ line: 4, column: 4 });
  });
  test("nrpowt in a procedure body outside a repeat is a parse-time error", () => {
    expect(run("oto p\n np nrpowt\njuż\npowtorz 2 [p]", "2d").error).toMatchObject({ line: 2, column: 5 });
  });
  test("wrong number of arguments", () => {
    expect(run(square + "kwadrat 80", "2d").error).toMatchObject({ line: 4, column: 1 });
    expect(run(square + "powtorz 1 [kwadrat 80]", "2d").error).toMatchObject({ line: 4, column: 22 });
    expect(run(square + "kwadrat 1 2 3", "2d").error).toMatchObject({ line: 4, column: 13 });
  });
  test("definition errors: inside a body, missing już, duplicate name", () => {
    expect(run("powtorz 2 [\noto p\njuż\n]", "2d").error).toMatchObject({ line: 2, column: 1 });
    expect(run("oto p\n np 1\n", "2d").error).toMatchObject({ line: 1, column: 1 });
    expect(run("oto p\njuż\noto P\njuż", "2d").error).toMatchObject({ line: 3, column: 5 });
    expect(run("oto p\noto q\njuż\njuż", "2d").error).toMatchObject({ line: 2, column: 1 });
  });
  test("variables may not be named after a procedure", () => {
    expect(run("oto p\njuż\nniech p 1", "2d").error).toMatchObject({ line: 3, column: 7 });
  });
});
EOF
bun test tests 2>&1 | grep -E "^\(fail| pass| fail" | head -20

