describe("run: 3D orientation", () => {
  const end = (src: string) => { const { segments, error } = run(src, "3d"); expect(error).toBeNull(); return r(segments[segments.length - 1].to); };
  test("gora 90 heads along the former up vector", () => {
    expect(end("gora 90 np 10")).toEqual([0, 0, 10]);
    expect(end("pitchdown 90 fd 10")).toEqual([0, 0, -10]);
    expect(end("góra 90 dół 90 np 10")).toEqual([0, 10, 0]);
  });
  test("pp 90: up becomes former right, right becomes former down; heading unchanged", () => {
    expect(end("pp 90 np 10")).toEqual([0, 10, 0]);
    expect(end("pp 90 gora 90 np 10")).toEqual([10, 0, 0]);
    expect(end("przechylprawo 90 pw 90 np 10")).toEqual([0, 0, -10]);
    expect(end("rl 90 gora 90 np 10")).toEqual([-10, 0, 0]);
  });
  test("pw turns about the turtle's own up vector after pitching", () => {
    expect(end("gora 90 pw 90 np 10")).toEqual([10, 0, 0]);
  });
  test("dom resets the full orientation", () => {
    expect(end("gora 45 pp 30 pod dom opu np 10")).toEqual([0, 10, 0]);
  });
  test("pitch and roll are errors in 2D mode, at the command", () => {
    expect(run("np 10\ngora 90", "2d")).toEqual({ segments: [], error: expect.objectContaining({ line: 2, column: 1 }) });
    expect(run("pl 5", "2d").error).toMatchObject({ column: 1 });
  });
  test("flat programs draw identical coordinates in 2D and 3D", () => {
    const src = "powtorz 5 [np 180 pw 144] ws 33.3 lw 17 np 12";
    expect(run(src, "3d")).toEqual(run(src, "2d"));
  });
  test("schody ends 6×35 forward and 6×20 up", () => {
    expect(end("powtorz 6 [\n  np 35\n  gora 90\n  np 20\n  dol 90\n]")).toEqual([0, 210, 120]);
  });
});
