describe("run: limits", () => {
  test("operation budget: 10,000 executed operations are allowed, one more is an error", () => {
    // repeat (1) + 4999 × (command + iteration finish) = 9999
    expect(run("powtorz 4999 [pw 0]\npw 0", "2d").error).toBeNull();
    const over = run("np 1\npowtorz 4999 [pw 0]\npw 0", "2d");
    expect(over.error).toMatchObject({ line: 3, column: 1 });
    expect(over.segments.length).toBe(1);
  });
  test("conditionals and calls count themselves and their finishing", () => {
    // per iteration: if(1) + np(1) + body finish(1) + iteration finish(1) = 4; 1 + 4×2500 = 10001
    expect(run("powtorz 2499 [jeśli 1 = 1 [np 0]] pw 0 pw 0 pw 0", "2d").error).toBeNull();
    expect(run("powtorz 2500 [jeśli 1 = 1 [np 0]]", "2d").error).not.toBeNull();
    // call(1) + body pw(1) + finish(1) = 3 per iteration, +1 iteration finish = 4
    expect(run("oto p\n pw 0\njuż\npowtorz 2499 [p] pw 0 pw 0 pw 0", "2d").error).toBeNull();
    expect(run("oto p\n pw 0\njuż\npowtorz 2500 [p]", "2d").error).not.toBeNull();
  });
  test("runaway recursion hits the 32-frame limit at the call", () => {
    const res = run("oto r\n np 1\n r\njuż\nr", "2d");
    expect(res.error).toMatchObject({ line: 3, column: 2 });
    expect(res.segments.length).toBe(32);
  });
  test("32 nested repeats run, 33 are too deep", () => {
    const nest = (n: number) => "powtorz 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(nest(32), "2d").error).toBeNull();
    expect(run(nest(33), "2d").error).toMatchObject({ column: 1 + 11 * 32 + 8 });
  });
  test("segment limit counts kept segments", () => {
    expect(run("powtorz 4000 [np 1 pw 180]", "2d").error).toBeNull();
    expect(run("powtorz 3 [czysc powtorz 3000 [np 1 pw 180]]", "2d").error).toBeNull();
    const res = run("pod powtorz 2 [np 0] opu powtorz 3333 [np 1 pw 180 np 1 pw 180 np 1]\nnp 1", "2d");
    expect(res.error).toBeNull();
    expect(run("powtorz 3334 [np 1 pw 180 np 1]", "2d").error).not.toBeNull();
  });
  test("coordinates beyond ±100,000 are an error at the move", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    const res = run("np 5\nnp 99996", "2d");
    expect(res.error).toMatchObject({ line: 2, column: 1 });
    expect(res.segments.length).toBe(1);
  });
  test("source and token limits", () => {
    expect(run("np 1 " + " ".repeat(50000), "2d").error).not.toBeNull();
    expect(run("pw 0 ".repeat(5000), "2d").error).toBeNull();
    expect(run("pw 0 ".repeat(5000) + "np", "2d").error).toMatchObject({ column: 25001 });
  });
});
EOF
