import { describe, expect, test } from "bun:test";
import { Runner } from "../src/runner";
import { run } from "../src/lang";

/** manual clock: the test decides when animation frames happen */
function manualClock() {
  let cb: (() => void) | null = null;
  return {
    schedule: (f: () => void) => { cb = f; return () => { cb = null; }; },
    tick() { const f = cb; cb = null; f?.(); },
    get pending() { return cb !== null; },
  };
}

const prog = "np 10\npw 90\nnp 5";

describe("Runner: stepping", () => {
  test("loading highlights the first command; each step executes one command", () => {
    const r = new Runner(manualClock());
    r.load(prog, "2d");
    expect(r.state).toMatchObject({ status: "paused", line: 1, segments: [] });
    r.step();
    expect(r.state).toMatchObject({ status: "paused", line: 2 });
    expect(r.state.segments.length).toBe(1);
    r.step();
    expect(r.state.line).toBe(3);
    expect(r.state.turtle.heading.map(Math.round)).toEqual([1, 0, 0]);
    r.step();
    expect(r.state.status).toBe("done");
    expect(r.state.segments.length).toBe(2);
    expect(r.state.line).toBeNull();
  });
  test("a parse error draws nothing and reports the position", () => {
    const r = new Runner(manualClock());
    r.load("np 10\nnp )", "2d");
    expect(r.state).toMatchObject({ status: "error", segments: [], error: { line: 2, column: 4 } });
  });
  test("a run-time error while stepping keeps what was drawn", () => {
    const r = new Runner(manualClock());
    r.load("np 10\nnp 1 / 0", "2d");
    r.step(); r.step();
    expect(r.state).toMatchObject({ status: "error", error: { line: 2, column: 4 } });
    expect(r.state.segments.length).toBe(1);
  });
});

describe("Runner: animated run", () => {
  test("play advances on clock ticks, pause holds, resume finishes with run()'s result", () => {
    const clock = manualClock();
    const r = new Runner(clock);
    r.speed = 1; // one command per tick
    r.load(prog, "2d");
    r.play();
    expect(r.state.status).toBe("running");
    clock.tick();
    expect(r.state.segments.length).toBe(1);
    r.pause();
    expect(r.state.status).toBe("paused");
    expect(clock.pending).toBe(false);
    r.play();
    while (clock.pending) clock.tick();
    expect(r.state.status).toBe("done");
    expect(r.state.segments).toEqual(run(prog, "2d").segments);
  });
  test("reset forgets the drawing and returns the turtle home", () => {
    const clock = manualClock();
    const r = new Runner(clock);
    r.load(prog, "2d");
    r.finish();
    r.reset();
    expect(r.state).toMatchObject({ status: "idle", segments: [], line: null, error: null });
    expect(r.state.turtle.pos).toEqual([0, 0, 0]);
    expect(clock.pending).toBe(false);
  });
  test("finish runs to the end without animation and can be repeated", () => {
    const r = new Runner(manualClock());
    for (let k = 0; k < 2; k++) {
      r.load(prog, "2d");
      r.finish();
      expect(r.state.status).toBe("done");
      expect(r.state.segments).toEqual(run(prog, "2d").segments);
    }
  });
  test("subscribers hear every change", () => {
    const r = new Runner(manualClock());
    const seen: string[] = [];
    r.subscribe((s) => seen.push(s.status));
    r.load(prog, "2d");
    r.finish();
    expect(seen).toEqual(["paused", "done"]);
  });
});
