import { initialTurtle, prepare, toRunError, type Execution, type Mode, type RunError, type Segment, type Turtle } from "./lang";

export interface Clock {
  /** call `f` once on the next animation frame; returns a cancel function */
  schedule(f: () => void): () => void;
}

export type Status = "idle" | "running" | "paused" | "done" | "error";

export interface RunnerState {
  status: Status;
  mode: Mode;
  segments: Segment[];
  turtle: Turtle;
  /** position of the next command to execute */
  line: number | null;
  column: number | null;
  error: RunError | null;
}

export const browserClock: Clock = {
  schedule(f) {
    const id = requestAnimationFrame(f);
    return () => cancelAnimationFrame(id);
  },
};

/**
 * Drives one program: step, play (animated), pause, finish, reset.
 * The UI's transport buttons and the testing hook both go through this.
 */
export class Runner {
  /** commands executed per animation frame; fractions spread one command over several frames */
  speed = 4;
  state: RunnerState = { status: "idle", mode: "2d", segments: [], turtle: initialTurtle(), line: null, column: null, error: null };
  private exec: Execution | null = null;
  private cancel: (() => void) | null = null;
  private credit = 0;
  private listeners = new Set<(s: RunnerState) => void>();

  constructor(private clock: Clock) {}

  subscribe(f: (s: RunnerState) => void): () => void {
    this.listeners.add(f);
    return () => this.listeners.delete(f);
  }

  private emit() {
    for (const f of this.listeners) f(this.state);
  }

  private set(patch: Partial<RunnerState>) {
    this.state = { ...this.state, ...patch };
    if (this.exec) this.state.segments = this.exec.machine.segments;
    this.emit();
  }

  /** parses the program and stands before its first command */
  load(source: string, mode: Mode) {
    this.stopClock();
    this.exec = null;
    try {
      const ex = prepare(source, mode);
      this.exec = ex;
      if (ex.first) this.set({ status: "paused", mode, turtle: ex.machine.t, line: ex.first.line, column: ex.first.column, error: null });
      else this.set({ status: "done", mode, turtle: ex.machine.t, line: null, column: null, error: null });
    } catch (e) {
