import type { Mode } from "./lang";
import { EXAMPLES } from "./examples";

/** the subset of Web Storage we use; localStorage in the browser */
export interface KeyValue {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function memoryStorage(): KeyValue {
  const m = new Map<string, string>();
  return { getItem: (k) => m.get(k) ?? null, setItem: (k, v) => void m.set(k, v) };
}

const KEY = "logomocja:v1:";

const starter: Record<Mode, string> = {
  "2d": EXAMPLES.find((e) => e.mode === "2d")!.source,
  "3d": EXAMPLES.find((e) => e.mode === "3d")!.source,
};

/** The user's program in each mode, persisted on every edit. */
export class Workspace {
  mode: Mode;
  private drafts: Record<Mode, string>;

  constructor(private store: KeyValue) {
    const saved = (m: Mode) => store.getItem(KEY + "draft:" + m);
    this.drafts = { "2d": saved("2d") ?? starter["2d"], "3d": saved("3d") ?? starter["3d"] };
    this.mode = store.getItem(KEY + "mode") === "3d" ? "3d" : "2d";
  }

  get source() { return this.drafts[this.mode]; }

  draft(mode: Mode) { return this.drafts[mode]; }

  setMode(mode: Mode) {
    this.mode = mode;
    this.store.setItem(KEY + "mode", mode);
  }

  edit(source: string) {
    this.drafts[this.mode] = source;
    this.store.setItem(KEY + "draft:" + this.mode, source);
  }
}
