import type { Mode } from "./lang";

const toB64url = (bytes: Uint8Array) => {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

const fromB64url = (s: string) => {
  const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
};

/** `#/p/<mode>/<base64url UTF-8 source>` — works under any base path, no server needed */
export function permalinkHash(source: string, mode: Mode): string {
  return `#/p/${mode}/${toB64url(new TextEncoder().encode(source))}`;
}

export function readPermalink(hash: string): { source: string; mode: Mode } | null {
  const m = /^#\/p\/(2d|3d)\/([A-Za-z0-9_-]*)$/.exec(hash);
  if (!m) return null;
  try {
    return { mode: m[1] as Mode, source: new TextDecoder("utf-8", { fatal: true }).decode(fromB64url(m[2])) };
  } catch {
    return null;
  }
}
EOF
