    hint: "oto kwadrat ma: bok … już, a potem kwadrat 40, kwadrat 80, kwadrat 120.",
    solution: "oto kwadrat ma: bok\n  powtorz 4 [np bok pw 90]\njuż\n\nkwadrat 40\nkwadrat 80\nkwadrat 120\n",
  },
  {
    id: "brama", title: "Pionowa brama", mode: "3d",
    task: "W trybie 3D narysuj kwadrat o boku 80 stojący pionowo: pierwszy bok idzie prosto w górę, potem skręcaj w prawo.",
    hint: "„gora 90” kieruje żółwia do nieba.",
    solution: "gora 90\npowtorz 4 [np 80 pw 90]\n",
  },
];

/** points every `step` units along the segments (both ends included) */
function samples(segs: Segment[], step: number): Vec[] {
  const out: Vec[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(len / step));
    for (let k = 0; k <= n; k++) {
      const f = k / n;
      out.push([s.from[0] + (s.to[0] - s.from[0]) * f, s.from[1] + (s.to[1] - s.from[1]) * f, s.from[2] + (s.to[2] - s.from[2]) * f]);
    }
  }
  return out;
}

function distToSeg(p: Vec, s: Segment): number {
  const d = [s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]];
  const w = [p[0] - s.from[0], p[1] - s.from[1], p[2] - s.from[2]];
  const dd = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
  const t = dd === 0 ? 0 : Math.max(0, Math.min(1, (w[0] * d[0] + w[1] * d[1] + w[2] * d[2]) / dd));
  return Math.hypot(w[0] - d[0] * t, w[1] - d[1] * t, w[2] - d[2] * t);
}

const near = (p: Vec, segs: Segment[], tol: number) => segs.some((s) => distToSeg(p, s) <= tol);
const where = (p: Vec, mode: Mode) =>
  "(" + p.slice(0, mode === "3d" ? 3 : 2).map((v) => Math.round(v)).join("; ") + ")";

export function targetOf(c: Challenge): Segment[] {
  return run(c.solution, c.mode).segments;
}

/**
 * Compares the user's drawing with the target, ignoring colour, width and
 * stroke order/direction. Tolerance: 1.5 units.
 */
export function checkChallenge(c: Challenge, source: string): { pass: boolean; reason: string } {
  const res = run(source, c.mode);
  if (res.error) return { pass: false, reason: `Program ma błąd (wiersz ${res.error.line}, kolumna ${res.error.column}): ${res.error.message}` };
  if (res.segments.length === 0) return { pass: false, reason: "Program niczego nie narysował." };
  const target = targetOf(c), tol = 1.5;
  const missing = samples(target, 2).find((p) => !near(p, res.segments, tol));
  if (missing) return { pass: false, reason: `Brakuje części rysunku w okolicy punktu ${where(missing, c.mode)}.` };
  const extra = samples(res.segments, 2).find((p) => !near(p, target, tol));
  if (extra) return { pass: false, reason: `Rysunek ma dodatkowe linie, np. w okolicy punktu ${where(extra, c.mode)}.` };
  return { pass: true, reason: "Zgadza się! Rysunek pokrywa się z wzorem." };
}

const PKEY = "logomocja:v1:challenges";

/** solved challenges and the last attempt at each, in local storage */
export class Progress {
  private data: { solved: string[]; code: Record<string, string> };
  constructor(private store: KeyValue) {
    try {
      this.data = JSON.parse(store.getItem(PKEY) ?? "") ?? { solved: [], code: {} };
    } catch {
      this.data = { solved: [], code: {} };
    }
  }
  isSolved(id: string) { return this.data.solved.includes(id); }
  get solvedCount() { return this.data.solved.length; }
  code(id: string): string | undefined { return this.data.code[id]; }
  record(id: string, source: string, pass: boolean) {
    this.data.code[id] = source;
    if (pass && !this.isSolved(id)) this.data.solved.push(id);
    this.store.setItem(PKEY, JSON.stringify(this.data));
  }
}
