import { highlight } from "./highlight";
import type { RunError } from "../lang";

/**
 * A textarea laid over a highlighted copy of its text. The overlay carries
 * line numbers, the executing-line band and the inline error marker.
 */
export class Editor {
  readonly textarea: HTMLTextAreaElement;
  private code: HTMLElement;
  private gutter: HTMLElement;
  private band: HTMLElement;
  private errRow: HTMLElement;
  private errMark: HTMLElement;
  private bubble: HTMLElement;
  private error: RunError | null = null;
  private lines = 0;

  constructor(root: HTMLElement, private onInput: (value: string) => void) {
    root.classList.add("editor");
    root.innerHTML = `
      <div class="ed-scroll">
        <div class="ed-inner">
          <div class="ed-gutter" aria-hidden="true"></div>
          <div class="ed-band" hidden></div>
          <div class="ed-err-row" hidden></div>
          <pre class="ed-hl" aria-hidden="true"><code></code></pre>
          <span class="ed-err-mark" hidden></span>
          <textarea class="ed-input" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" wrap="off"
            aria-label="Program w języku Logo" aria-describedby="ed-error"></textarea>
          <div class="ed-bubble" id="ed-error" role="status" hidden></div>
        </div>
      </div>`;
    this.textarea = root.querySelector("textarea")!;
    this.code = root.querySelector(".ed-hl code")!;
    this.gutter = root.querySelector(".ed-gutter")!;
    this.band = root.querySelector(".ed-band")!;
    this.errRow = root.querySelector(".ed-err-row")!;
    this.errMark = root.querySelector(".ed-err-mark")!;
    this.bubble = root.querySelector(".ed-bubble")!;
    this.textarea.addEventListener("input", () => {
      this.setError(null);
      this.render();
      this.onInput(this.textarea.value);
    });
    this.textarea.addEventListener("keydown", (e) => this.keys(e));
  }

  get value() { return this.textarea.value; }
  set value(v: string) {
    this.textarea.value = v;
    this.setError(null);
    this.render();
  }

  focus() { this.textarea.focus(); }

  private render() {
    const v = this.textarea.value;
    this.code.innerHTML = highlight(v);
    const n = v.split("\n").length;
    if (n !== this.lines) {
      this.lines = n;
      let g = "";
      for (let k = 1; k <= n; k++) g += `<span>${k}</span>`;
      this.gutter.innerHTML = g;
    }
    this.placeError();
  }

  /** 2 spaces for Tab, keep indentation on Enter; Esc leaves the editor (no focus trap) */
  private keys(e: KeyboardEvent) {
    const ta = this.textarea;
    if (e.key === "Tab" && !e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey && ta.dataset.tabMode !== "off") {
      e.preventDefault();
      document.execCommand("insertText", false, "  ");
    } else if (e.key === "Enter" && !e.ctrlKey && !e.metaKey && !e.shiftKey && !e.altKey) {
      const before = ta.value.slice(0, ta.selectionStart);
      const indent = /^[ \t]*/.exec(before.slice(before.lastIndexOf("\n") + 1))![0];
      if (indent) { e.preventDefault(); document.execCommand("insertText", false, "\n" + indent); }
    } else if (e.key === "Escape") {
      // first Escape is for pause (handled globally); Tab key mode toggles so keyboard users can leave
      ta.dataset.tabMode = ta.dataset.tabMode === "off" ? "on" : "off";
    }
  }

  setActiveLine(line: number | null) {
    this.band.hidden = line === null;
    if (line !== null) {
      this.band.style.setProperty("--line", String(line - 1));
      this.scrollToLine(line);
    }
  }

  setError(err: RunError | null) {
    this.error = err;
    this.errRow.hidden = this.errMark.hidden = this.bubble.hidden = !err;
    this.textarea.removeAttribute("aria-invalid");
    if (!err) { this.bubble.textContent = ""; return; }
    this.textarea.setAttribute("aria-invalid", "true");
    this.bubble.innerHTML = `<strong>Wiersz ${err.line}, kolumna ${err.column}.</strong> `;
    this.bubble.append(err.message);
    this.placeError();
    this.scrollToLine(err.line);
  }

  private placeError() {
    const err = this.error;
    if (!err) return;
    const lineText = this.textarea.value.split("\n")[err.line - 1] ?? "";
    const rest = lineText.slice(err.column - 1);
    const len = Math.max(1, (/^[^\s\[\]()]+/.exec(rest)?.[0].length ?? 1));
    for (const el of [this.errRow, this.errMark, this.bubble]) {
      el.style.setProperty("--line", String(err.line - 1));
      el.style.setProperty("--col", String(err.column - 1));
    }
    this.errMark.style.setProperty("--len", String(len));
  }

  private scrollToLine(line: number) {
    const sc = this.textarea.closest(".ed-scroll") as HTMLElement;
    const lh = parseFloat(getComputedStyle(this.textarea).lineHeight) || 22;
    const top = (line - 1) * lh;
    if (top < sc.scrollTop || top + lh * 3 > sc.scrollTop + sc.clientHeight)
      sc.scrollTop = Math.max(0, top - sc.clientHeight / 3);
  }
}
