import type { Segment, Turtle } from "../lang";
import { palette } from "./theme";

const RULER = 22;

/** nice tick step (1, 2, 5 × 10^n) so labels sit at least `px` apart */
export function tickStep(scale: number, px = 64): number {
  const raw = px / scale;
  const p = Math.pow(10, Math.floor(Math.log10(raw)));
  for (const m of [1, 2, 5, 10]) if (m * p >= raw) return m * p;
  return 10 * p;
}

const fmtTick = (v: number) => (Math.abs(v) < 1e-9 ? "0" : String(+v.toFixed(6)).replace(".", ",").replace("-", "−"));

/** Flat drawing surface: pan (drag, arrows), zoom (wheel, pinch, +/−), fit. */
export class View2D {
  segments: Segment[] = [];
  ghost: Segment[] | null = null;
  turtle: Turtle | null = null;
  grid = true;
  /** world point at the centre of the plot area, and pixels per unit */
  cx = 0; cy = 0; scale = 1.5;
  private dirty = true;
  private ctx: CanvasRenderingContext2D;
  private pointers = new Map<number, { x: number; y: number }>();
  private pinch = 0;
  onViewChange: (() => void) | null = null;

  constructor(public canvas: HTMLCanvasElement) {
    this.ctx = canvas.getContext("2d")!;
    new ResizeObserver(() => this.invalidate()).observe(canvas);
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();
      const r = canvas.getBoundingClientRect();
      this.zoomAt(Math.exp(-e.deltaY * 0.0015), e.clientX - r.left, e.clientY - r.top);
    }, { passive: false });
    canvas.addEventListener("pointerdown", (e) => {
      canvas.setPointerCapture(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      this.pinch = this.pinchDist();
      canvas.classList.add("grabbing");
    });
    canvas.addEventListener("pointermove", (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      const cur = { x: e.clientX, y: e.clientY };
      if (this.pointers.size === 1) {
        this.cx -= (cur.x - prev.x) / this.scale;
        this.cy += (cur.y - prev.y) / this.scale;
        this.invalidate();
      }
      this.pointers.set(e.pointerId, cur);
      if (this.pointers.size === 2) {
        const d = this.pinchDist();
        if (this.pinch > 0) {
          const r = canvas.getBoundingClientRect();
          const pts = [...this.pointers.values()];
          this.zoomAt(d / this.pinch, (pts[0].x + pts[1].x) / 2 - r.left, (pts[0].y + pts[1].y) / 2 - r.top);
        }
        this.pinch = d;
      }
    });
    const up = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      this.pinch = this.pinchDist();
      if (!this.pointers.size) canvas.classList.remove("grabbing");
    };
    canvas.addEventListener("pointerup", up);
    canvas.addEventListener("pointercancel", up);
    canvas.addEventListener("keydown", (e) => {
      const step = 40 / this.scale;
      const k: Record<string, () => void> = {
        ArrowLeft: () => (this.cx -= step), ArrowRight: () => (this.cx += step),
        ArrowUp: () => (this.cy += step), ArrowDown: () => (this.cy -= step),
        "+": () => this.zoom(1.25), "=": () => this.zoom(1.25), "-": () => this.zoom(0.8), "0": () => this.fit(),
      };
      if (k[e.key] && !e.ctrlKey && !e.metaKey) { e.preventDefault(); k[e.key](); this.invalidate(); }
    });
  }

  private pinchDist() {
    if (this.pointers.size !== 2) return 0;
    const [a, b] = [...this.pointers.values()];
    return Math.hypot(a.x - b.x, a.y - b.y);
  }

  private size() {
    return { w: this.canvas.clientWidth, h: this.canvas.clientHeight };
  }

  /** screen position of the plot centre (ruler strips excluded) */
  private centre() {
    const { w, h } = this.size();
    return { x: RULER + (w - RULER) / 2, y: RULER + (h - RULER) / 2 };
  }

  zoomAt(f: number, sx: number, sy: number) {
    const c = this.centre();
    const wx = this.cx + (sx - c.x) / this.scale, wy = this.cy - (sy - c.y) / this.scale;
    this.scale = Math.min(400, Math.max(0.002, this.scale * f));
    this.cx = wx - (sx - c.x) / this.scale;
    this.cy = wy + (sy - c.y) / this.scale;
    this.invalidate();
  }

  zoom(f: number) {
    const c = this.centre();
    this.zoomAt(f, c.x, c.y);
  }

  /** frame every stroke (and the ghost and turtle) with a margin */
  fit() {
    const pts: number[][] = [];
