import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { LineSegments2 } from "three/examples/jsm/lines/LineSegments2.js";
import { LineSegmentsGeometry } from "three/examples/jsm/lines/LineSegmentsGeometry.js";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import type { Segment, Turtle } from "../lang";
import { palette } from "./theme";

/** true when this browser can give us a WebGL context */
export function webglAvailable(): boolean {
  try {
    const c = document.createElement("canvas");
    return !!(c.getContext("webgl2") || c.getContext("webgl"));
  } catch {
    return false;
  }
}

/** Space view: orbit (drag), pan (right-drag / two fingers), zoom (wheel / pinch), grid and axes. */
export class View3D {
  segments: Segment[] = [];
  ghost: Segment[] | null = null;
  turtle: Turtle | null = null;
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(45, 1, 0.5, 2_000_000);
  private controls: OrbitControls;
  private strokes = new THREE.Group();
  private ghostGroup = new THREE.Group();
  private grid!: THREE.GridHelper;
  private axes = new THREE.Group();
  private turtleMesh: THREE.Group;
  private materials: LineMaterial[] = [];
  private dirty = false;
  private drawn = -1;
  private drawnRef: Segment[] | null = null;

  constructor(public canvas: HTMLCanvasElement) {
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
    this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
    this.camera.up.set(0, 0, 1);
    this.controls = new OrbitControls(this.camera, canvas);
    this.controls.enableDamping = false;
    this.controls.listenToKeyEvents(canvas as unknown as HTMLElement);
    this.controls.addEventListener("change", () => this.invalidate());
    this.scene.add(this.strokes, this.ghostGroup, this.axes);
    this.turtleMesh = this.makeTurtle();
    this.scene.add(this.turtleMesh);
    this.buildHelpers(400);
    new ResizeObserver(() => this.invalidate()).observe(canvas);
    this.resetCamera();
  }

  private makeTurtle() {
    const g = new THREE.Group();
    const P = palette();
    const body = new THREE.Mesh(new THREE.ConeGeometry(5, 16, 4), new THREE.MeshBasicMaterial({ color: P.turtle }));
    body.rotation.y = Math.PI / 4; // flat side towards up
    body.scale.set(1, 1, 0.45);
    g.add(body);
    // a short mast marks the up vector, so roll is visible
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 8), new THREE.MeshBasicMaterial({ color: P.turtle }));
    mast.rotation.x = Math.PI / 2;
    mast.position.set(0, -3, 4);
    g.add(mast);
    return g;
  }

  private buildHelpers(size: number) {
    const P = palette();
    if (this.grid) { this.scene.remove(this.grid); this.grid.geometry.dispose(); }
    const step = Math.pow(10, Math.ceil(Math.log10(size / 10)));
    const span = Math.ceil(size / step) * step * 2;
    this.grid = new THREE.GridHelper(span, span / step, new THREE.Color(P.axis), new THREE.Color(P.grid));
    this.grid.rotation.x = Math.PI / 2; // into the XY plane
    this.scene.add(this.grid);
    this.axes.clear();
    const len = span / 2;
    const axis = (to: [number, number, number], color: string) => {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(...to)]);
      this.axes.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
    };
    axis([len, 0, 0], "#d0503c");
    axis([0, len, 0], "#3b9a4f");
    axis([0, 0, len * 0.6], "#3d78c9");
