    for (const s of segs) {
      const w = ghost ? 6 : s.width;
      if (!byWidth.has(w)) byWidth.set(w, []);
      byWidth.get(w)!.push(s);
    }
    const col = new THREE.Color();
    for (const [w, list] of byWidth) {
      const pos = new Float32Array(list.length * 6), cols = new Float32Array(list.length * 6);
      list.forEach((s, k) => {
        pos.set([...s.from, ...s.to], k * 6);
        col.set(s.color);
        cols.set([col.r, col.g, col.b, col.r, col.g, col.b], k * 6);
      });
      const geo = new LineSegmentsGeometry();
      geo.setPositions(pos);
      if (!ghost) geo.setColors(cols);
      const line = new LineSegments2(geo, ghost ? this.material(w, { color: palette().ghost, opacity: 0.6, dashed: true }) : this.material(w));
      if (ghost) line.computeLineDistances();
      group.add(line);
    }
  }

  private bounds(): THREE.Box3 {
    const box = new THREE.Box3();
    for (const s of [...this.segments, ...(this.ghost ?? [])]) {
      box.expandByPoint(new THREE.Vector3(...s.from));
      box.expandByPoint(new THREE.Vector3(...s.to));
    }
    if (this.turtle) box.expandByPoint(new THREE.Vector3(...this.turtle.pos));
    return box;
  }

  fit() {
    const box = this.bounds();
    const sphere = box.isEmpty() ? new THREE.Sphere(new THREE.Vector3(), 120) : box.getBoundingSphere(new THREE.Sphere());
    const r = Math.max(sphere.radius, 20);
    const dist = r / Math.sin((this.camera.fov * Math.PI) / 360) * 1.15;
    const dir = new THREE.Vector3(0.9, -1.3, 1.0).normalize();
    this.controls.target.copy(sphere.center);
    this.camera.position.copy(sphere.center).addScaledVector(dir, dist);
    this.camera.near = Math.max(0.1, dist / 1000);
    this.camera.far = dist * 50;
    this.camera.updateProjectionMatrix();
    this.buildHelpers(Math.max(200, r * 1.5));
    this.controls.update();
    this.invalidate();
  }

  resetCamera() {
    const saved = [this.segments, this.ghost] as const;
    this.segments = []; this.ghost = null;
    const t = this.turtle; this.turtle = null;
    this.fit();
    [this.segments, this.ghost] = saved; this.turtle = t;
  }

  /** orbit by keyboard buttons: angles in degrees */
  orbit(dAz: number, dEl: number) {
    const off = this.camera.position.clone().sub(this.controls.target);
    const sph = new THREE.Spherical().setFromVector3(new THREE.Vector3(off.x, off.z, -off.y));
    sph.theta += (dAz * Math.PI) / 180;
    sph.phi = Math.min(Math.PI - 0.05, Math.max(0.05, sph.phi - (dEl * Math.PI) / 180));
    const v = new THREE.Vector3().setFromSpherical(sph);
    this.camera.position.copy(this.controls.target).add(new THREE.Vector3(v.x, -v.z, v.y));
    this.controls.update();
  }

  zoom(f: number) {
    const off = this.camera.position.clone().sub(this.controls.target).multiplyScalar(1 / f);
    this.camera.position.copy(this.controls.target).add(off);
    this.controls.update();
  }

  invalidate() {
    if (this.dirty) return;
    this.dirty = true;
    requestAnimationFrame(() => this.draw());
  }

  draw() {
    this.dirty = false;
    const w = this.canvas.clientWidth, h = this.canvas.clientHeight;
    if (!w || !h) return;
    const size = this.renderer.getSize(new THREE.Vector2());
    if (size.x !== w || size.y !== h) this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    for (const m of this.materials) m.resolution.set(w, h);
    if (this.drawnRef !== this.segments || this.drawn !== this.segments.length) {
      this.build(this.strokes, this.segments, false);
      this.drawnRef = this.segments;
      this.drawn = this.segments.length;
    }
    const P = palette();
    this.scene.background = new THREE.Color(P.paper);
    const t = this.turtle;
    this.turtleMesh.visible = !!t;
    if (t) {
      const m = new THREE.Matrix4().makeBasis(new THREE.Vector3(...t.right), new THREE.Vector3(...t.heading), new THREE.Vector3(...t.up));
      this.turtleMesh.quaternion.setFromRotationMatrix(m);
      this.turtleMesh.position.set(...t.pos);
      const dist = this.camera.position.distanceTo(this.controls.target);
      this.turtleMesh.scale.setScalar(Math.max(0.3, dist / 400));
    }
    this.renderer.render(this.scene, this.camera);
  }

  setGhost(g: Segment[] | null) {
    this.ghost = g;
    this.build(this.ghostGroup, g ?? [], true);
    this.invalidate();
  }

  /** theme switch: rebuild colours */
  restyle() {
    this.scene.remove(this.turtleMesh);
    this.turtleMesh = this.makeTurtle();
    this.scene.add(this.turtleMesh);
    this.buildHelpers(400);
    this.setGhost(this.ghost);
    this.drawn = -1;
    this.invalidate();
  }

  toPNG(): Promise<Blob> {
    const g = this.ghostGroup.visible;
    this.ghostGroup.visible = false;
    this.draw();
    this.ghostGroup.visible = g;
    return new Promise((res, rej) => this.canvas.toBlob((b) => (b ? res(b) : rej(new Error("toBlob"))), "image/png"));
  }
}
