import type { Mode, Segment, Vec } from "../lang";
import { palette } from "./theme";

/** projects 3D points the way the 3D view's default camera roughly sees them */
function project(p: Vec, mode: Mode): [number, number] {
  if (mode === "2d") return [p[0], p[1]];
  const az = (-34 * Math.PI) / 180, el = (32 * Math.PI) / 180;
  const x = p[0] * Math.cos(az) - p[1] * Math.sin(az);
  const d = p[0] * Math.sin(az) + p[1] * Math.cos(az);
  return [x, p[2] * Math.cos(el) + d * Math.sin(el)];
}

/** paints a drawing scaled into the canvas; `dashed` draws a target outline */
export function paintThumb(canvas: HTMLCanvasElement, segs: Segment[], mode: Mode, dashed = false) {
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth || 160, h = canvas.clientHeight || 120;
  canvas.width = w * dpr; canvas.height = h * dpr;
  const ctx = canvas.getContext("2d")!;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const P = palette();
  ctx.fillStyle = P.paper;
  ctx.fillRect(0, 0, w, h);
  const pts = segs.map((s) => [project(s.from, mode), project(s.to, mode)]);
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const pair of pts) for (const [x, y] of pair) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  if (!pts.length) return;
  const pad = 12;
  const sc = Math.min((w - pad * 2) / Math.max(x1 - x0, 1), (h - pad * 2) / Math.max(y1 - y0, 1));
  const ox = w / 2 - ((x0 + x1) / 2) * sc, oy = h / 2 + ((y0 + y1) / 2) * sc;
  ctx.lineCap = "round"; ctx.lineJoin = "round";
  if (dashed) ctx.setLineDash([4, 4]);
  pts.forEach(([[ax, ay], [bx, by]], k) => {
    ctx.strokeStyle = dashed ? P.rulerInk : segs[k].color;
    ctx.lineWidth = dashed ? 1.75 : Math.max(1, Math.min(2.5, segs[k].width * 0.6));
    ctx.beginPath();
    ctx.moveTo(ox + ax * sc, oy - ay * sc);
    ctx.lineTo(ox + bx * sc, oy - by * sc);
    ctx.stroke();
  });
}
