import "./styles.css";
import { run, type Mode, type RunResult, type Segment } from "./lang";
import { Runner, browserClock, type RunnerState } from "./runner";
import { Workspace } from "./workspace";
import { EXAMPLES, type Example } from "./examples";
import { CHALLENGES, Progress, checkChallenge, targetOf, type Challenge } from "./challenges";
import { permalinkHash, readPermalink } from "./share";
import { Editor } from "./ui/editor";
import { View2D } from "./ui/view2d";
import type { View3D } from "./ui/view3d";
import { referenceHTML } from "./ui/reference";
import { paintThumb } from "./ui/thumbs";
import { applyTheme, storedTheme, type ThemeChoice } from "./ui/theme";

const VERSION = "1.0.0";
const $ = <T extends HTMLElement = HTMLElement>(sel: string) => document.querySelector(sel) as T;

/** speed slider position → commands per animation frame (10 = all at once) */
const SPEEDS = [0.04, 0.1, 0.25, 0.5, 1, 2, 5, 15, 60, Infinity];
const SPEED_LABELS = ["bardzo wolno", "wolno", "spokojnie", "umiarkowanie", "średnio", "żwawo", "szybko", "bardzo szybko", "błyskawicznie", "od razu"];

const workspace = new Workspace(localStorage);
const progress = new Progress(localStorage);
const runner = new Runner(browserClock);

/** what the editor is holding: the per-mode draft, or a challenge attempt */
let context: { kind: "draft" } | { kind: "challenge"; challenge: Challenge } = { kind: "draft" };
let mode: Mode = workspace.mode;

const editor = new Editor($("#editor"), (value) => {
  if (context.kind === "draft") workspace.edit(value);
  else progress.record(context.challenge.id, value, false);
  if (runner.state.status !== "idle" && runner.state.status !== "stale") runner.halt();
  $("#verdict").textContent = "";
  $("#verdict").className = "verdict";
  hideShare();
});

// ---------- views ----------

const view2d = new View2D($<HTMLCanvasElement>("#c2d"));
let view3d: View3D | null = null;
let view3dLoading: Promise<View3D | null> | null = null;
let glReason: string | null = null;

function ensure3D(): Promise<View3D | null> {
  if (view3d) return Promise.resolve(view3d);
  if (view3dLoading) return view3dLoading;
  view3dLoading = import("./ui/view3d")
    .then((m) => {
      if (!m.webglAvailable()) throw new Error("no-webgl");
      view3d = new m.View3D($<HTMLCanvasElement>("#c3d"));
      syncView(true);
      return view3d;
    })
    .catch((e) => {
      glReason = String(e?.message) === "no-webgl"
        ? "Widok 3D jest wyłączony, bo ta przeglądarka nie udostępnia WebGL (może być wyłączony w ustawieniach lub nieobsługiwany przez kartę graficzną)."
        : "Widok 3D jest wyłączony, bo nie udało się uruchomić grafiki WebGL.";
      updateModeUI();
      return null;
    });
  return view3dLoading;
}

/** in 3D mode without WebGL, the 2D canvas shows the top-down projection */
const using3D = () => mode === "3d" && !!view3d && !glReason;

function activeView() {
  return using3D() ? view3d! : view2d;
}

function syncView(fit = false) {
  const s = runner.state;
  for (const v of [view2d, view3d]) {
    if (!v) continue;
    v.segments = s.segments;
    v.turtle = s.turtle;
  }
  if (fit) activeView().fit();
  else activeView().invalidate();
  updateReadout(s);
}

const fmt = (v: number) => (Math.round(v * 10) / 10).toLocaleString("pl-PL", { maximumFractionDigits: 1 }).replace("-", "−");

function updateReadout(s: RunnerState) {
  const t = s.turtle;
  const pos = mode === "3d" ? `x ${fmt(t.pos[0])}  y ${fmt(t.pos[1])}  z ${fmt(t.pos[2])}` : `x ${fmt(t.pos[0])}  y ${fmt(t.pos[1])}`;
  const deg = ((Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI + 360) % 360;
  $("#readout").textContent = `${pos}   kierunek ${fmt(deg)}°   ${t.penDown ? "pisak w dół" : "pisak w górze"}   odcinki ${s.segments.length}`;
}

// ---------- runner → UI ----------

let lastStatus = "";
runner.subscribe((s) => {
  const animating = s.status === "running";
  editor.setActiveLine(s.status === "running" || s.status === "paused" ? s.line : null);
  if (s.status === "error" && s.error) editor.setError(s.error);
  const pause = $<HTMLButtonElement>("#pause-btn");
  pause.disabled = !(s.status === "running" || s.status === "paused");
  pause.querySelector("span")!.textContent = s.status === "paused" ? "Wznów" : "Pauza";
  pause.querySelector("use")!.setAttribute("href", s.status === "paused" ? "#i-play" : "#i-pause");
  $("#studio").dataset.status = s.status;
  const where = s.line ? `wiersz ${s.line}` : "";
  const msg =
    s.status === "running" ? `Rysuję… ${where}` :
    s.status === "paused" ? `Pauza przed poleceniem: ${where}, kolumna ${s.column}. Krok wykona je, Wznów dokończy program.` :
    s.status === "done" ? `Gotowe. ${s.segments.length} ${plural(s.segments.length, "odcinek", "odcinki", "odcinków")}.` :
    s.status === "error" ? (s.segments.length ? `Program zatrzymał błąd. Rysunek pokazuje to, co powstało przed nim.` : `Błąd w zapisie programu, nic nie zostało narysowane.`) :
    s.status === "stale" ? "Program zmieniony. Uruchom go ponownie, by zobaczyć nowy rysunek." : "Naciśnij Uruchom, aby narysować program.";
  // announce state changes, not every animation frame
  if (!animating || lastStatus !== s.status) $("#status").textContent = msg;
  lastStatus = s.status;
  syncView(s.status === "done" && fitOnDone);
  if (s.status === "done" || s.status === "error") fitOnDone = false;
});

let fitOnDone = false;

const plural = (n: number, one: string, few: string, many: string) =>
  n === 1 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? few : many;

function speedValue() {
  return SPEEDS[Number($<HTMLInputElement>("#speed").value) - 1];
}

// ---------- transport ----------

function runProgram(opts: { animate?: boolean; fit?: boolean } = {}) {
  hideShare();
  editor.setError(null);
  runner.load(editor.value, mode);
  const speed = speedValue();
  fitOnDone = opts.fit ?? false;
  if (opts.animate === false || speed === Infinity) runner.finish();
  else { runner.speed = speed; runner.play(); }
}

function step() {
  if (!runner.loaded) {
    editor.setError(null);
    runner.load(editor.value, mode);
  }
  runner.step();
}

function togglePause() {
  if (runner.state.status === "running") runner.pause();
  else if (runner.state.status === "paused") { runner.speed = Math.min(speedValue(), 1e6); runner.play(); }
}

function reset() {
  editor.setError(null);
  runner.reset();
  view2d.invalidate();
  view3d?.invalidate();
}

$("#run-btn").addEventListener("click", () => runProgram());
$("#step-btn").addEventListener("click", step);
$("#pause-btn").addEventListener("click", togglePause);
$("#reset-btn").addEventListener("click", reset);
const speed = $<HTMLInputElement>("#speed");
const speedText = () => speed.setAttribute("aria-valuetext", SPEED_LABELS[Number(speed.value) - 1]);
speed.value = localStorage.getItem("logomocja:v1:speed") ?? "6";
speedText();
speed.addEventListener("input", () => {
  speedText();
  localStorage.setItem("logomocja:v1:speed", speed.value);
  // retime a running program without restarting it
  if (runner.state.status === "running") {
    const v = speedValue();
    if (v === Infinity) runner.finish();
    else runner.speed = v;
  }
});

document.addEventListener("keydown", (e) => {
  const mod = e.ctrlKey || e.metaKey;
  if (!mod || $("#studio").hidden) return;
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); runProgram(); }
  else if (e.key === "Enter" && e.shiftKey) { e.preventDefault(); step(); }
  else if (e.key === ".") { e.preventDefault(); togglePause(); }
  else if (e.key === "Backspace" && e.shiftKey) { e.preventDefault(); reset(); }
});

// ---------- view tools ----------

document.querySelectorAll<HTMLButtonElement>("[data-view]").forEach((b) =>
  b.addEventListener("click", () => {
    const v = activeView();
    const a = b.dataset.view;
    if (a === "fit") v.fit();
    else if (a === "in") v.zoom(1.25);
    else if (a === "out") v.zoom(0.8);
    else if (a === "grid") {
      view2d.grid = !view2d.grid;
      b.setAttribute("aria-pressed", String(view2d.grid));
      view2d.invalidate();
    } else if (view3d && using3D()) {
      if (a === "left") view3d.orbit(-15, 0);
      if (a === "right") view3d.orbit(15, 0);
      if (a === "up") view3d.orbit(0, 12);
      if (a === "down") view3d.orbit(0, -12);
      if (a === "camera") view3d.fit();
    }
  }),
);

// ---------- mode ----------

function updateModeUI() {
  document.querySelectorAll<HTMLButtonElement>("#mode-switch [data-mode]").forEach((b) => {
    b.setAttribute("aria-checked", String(b.dataset.mode === mode));
    b.tabIndex = b.dataset.mode === mode ? 0 : -1;
  });
  const locked = context.kind === "challenge";
  document.querySelectorAll<HTMLButtonElement>("#mode-switch button").forEach((b) => (b.disabled = locked && b.dataset.mode !== mode));
  const stage = $("#stage");
  stage.dataset.mode = mode;
  const show3d = using3D();
  $("#c3d").hidden = !show3d;
  $("#c2d").hidden = show3d;
  const note = $("#gl-note");
  note.hidden = !(mode === "3d" && glReason);
  if (glReason) note.textContent = glReason + " Programy 3D nadal działają; obok widać ich rzut z góry na płaszczyznę XY.";
  stage.dataset.flat = String(!show3d);
  $("#code-title").textContent = context.kind === "challenge" ? `Rozwiązanie: ${context.challenge.title}` : `Szkic ${mode.toUpperCase()}`;
}

async function setMode(m: Mode, opts: { run?: boolean } = {}) {
  runner.reset();
  mode = m;
  if (context.kind === "draft") {
    workspace.setMode(m);
    editor.value = workspace.source;
  }
  updateModeUI();
  if (m === "3d") await ensure3D();
  updateModeUI();
  if (opts.run !== false) runProgram({ animate: false, fit: true });
}

document.querySelectorAll<HTMLButtonElement>("#mode-switch [data-mode]").forEach((b) => {
  b.addEventListener("click", () => { if (b.dataset.mode !== mode) void setMode(b.dataset.mode as Mode); });
  b.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      const other = $<HTMLButtonElement>(`#mode-switch [data-mode="${mode === "2d" ? "3d" : "2d"}"]`);
      if (!other.disabled) { other.focus(); other.click(); }
    }
  });
});

// ---------- theme ----------

const THEME_NAMES: Record<ThemeChoice, string> = { auto: "systemowy", light: "jasny", dark: "ciemny" };
function setTheme(t: ThemeChoice) {
  applyTheme(t);
  $("#theme-btn").setAttribute("aria-label", `Motyw: ${THEME_NAMES[t]}. Zmień motyw`);
  $("#theme-btn").title = `Motyw: ${THEME_NAMES[t]}`;
  view2d.invalidate();
  view3d?.restyle();
  renderThumbs();
}
$("#theme-btn").addEventListener("click", () => {
  const order: ThemeChoice[] = ["auto", "light", "dark"];
  setTheme(order[(order.indexOf(storedTheme()) + 1) % 3]);
});
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => { if (storedTheme() === "auto") setTheme("auto"); });

// ---------- toast ----------

let toastTimer = 0;
function toast(text: string, action?: { label: string; run: () => void }) {
  const el = $("#toast");
  el.innerHTML = "";
  const p = document.createElement("span");
  p.textContent = text;
  el.append(p);
  if (action) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "btn btn-small";
    b.textContent = action.label;
    b.addEventListener("click", () => { el.hidden = true; action.run(); });
    el.append(b);
  }
  const close = document.createElement("button");
  close.type = "button";
  close.className = "btn-icon btn-small";
  close.setAttribute("aria-label", "Zamknij powiadomienie");
  close.innerHTML = `<svg class="i"><use href="#i-plus" transform="rotate(45 12 12)"/></svg>`;
  close.addEventListener("click", () => (el.hidden = true));
  el.append(close);
  el.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => (el.hidden = true), 12000);
}

function keptToast(m: Mode) {
  toast(`Twój poprzedni szkic ${m.toUpperCase()} został zachowany.`, {
    label: "Przywróć szkic",
    run: () => {
      workspace.restoreDraft(m);
      enterDraft();
      editor.value = workspace.source;
      runProgram({ animate: false, fit: true });
      toast("Przywrócono szkic. Zastąpiony program też da się przywrócić tym samym sposobem.");
    },
  });
}

// ---------- loading programs ----------

function enterDraft() {
  if (context.kind === "challenge") {
    context = { kind: "draft" };
    $("#task").hidden = true;
    view2d.ghost = null;
    view3d?.setGhost(null);
  }
}

/** puts a program into the draft of `m` (keeping the old draft) and shows it */
async function loadIntoDraft(source: string, m: Mode, opts: { animate?: boolean } = {}) {
  enterDraft();
  const { keptDraft } = workspace.loadProgram(source, m);
  runner.reset();
  mode = m;
  editor.value = workspace.source;
  updateModeUI();
  if (m === "3d") await ensure3D();
  updateModeUI();
  runProgram({ animate: opts.animate ?? false, fit: true });
  if (keptDraft) keptToast(m);
}

function loadExample(ex: Example) {
  location.hash = "#/";
  void loadIntoDraft(ex.source, ex.mode, { animate: true });
}

// ---------- files & sharing ----------

function download(blob: Blob, name: string) {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

const fileBase = () => (context.kind === "challenge" ? `zadanie-${context.challenge.id}` : `logomocja-${mode}`);

$("#save-btn").addEventListener("click", () => download(new Blob([editor.value], { type: "text/plain;charset=utf-8" }), fileBase() + ".logo"));
$("#png-btn").addEventListener("click", async () => {
  try {
    download(await activeView().toPNG(), fileBase() + ".png");
  } catch {
    toast("Nie udało się zapisać obrazu.");
  }
});
$("#open-btn").addEventListener("click", () => $<HTMLInputElement>("#file-input").click());
$<HTMLInputElement>("#file-input").addEventListener("change", async (e) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  if (file.size > 1_000_000) { toast("Ten plik jest za duży jak na program Logo."); return; }
  const text = (await file.text()).replace(/\r\n?/g, "\n");
  if (context.kind === "challenge") {
    editor.value = text;
    progress.record(context.challenge.id, text, false);
    runProgram({ animate: false });
  } else {
    await loadIntoDraft(text, mode);
  }
  toast(`Otwarto plik „${file.name}”.`);
});

function hideShare() {
  $("#share-panel").hidden = true;
  $("#link-btn").setAttribute("aria-expanded", "false");
}
$("#link-btn").addEventListener("click", () => {
  const panel = $("#share-panel");
  if (!panel.hidden) { hideShare(); return; }
  const url = location.href.split("#")[0] + permalinkHash(editor.value, mode);
  const input = $<HTMLInputElement>("#share-url");
  input.value = url;
  panel.hidden = false;
  $("#link-btn").setAttribute("aria-expanded", "true");
  input.focus();
  input.select();
});
$("#copy-btn").addEventListener("click", async () => {
  const input = $<HTMLInputElement>("#share-url");
  try {
    await navigator.clipboard.writeText(input.value);
    toast("Link skopiowany do schowka.");
  } catch {
    input.select();
    toast("Nie mam dostępu do schowka. Link jest zaznaczony: skopiuj go skrótem Ctrl+C.");
  }
});

// ---------- challenges ----------

function openChallenge(ch: Challenge) {
  context = { kind: "challenge", challenge: ch };
  $("#task").hidden = false;
  $("#task-title").textContent = ch.title;
  $("#task-text").textContent = ch.task;
  $("#task-hint").textContent = ch.hint;
  $("#task-mode").textContent = ch.mode === "3d" ? "Tryb 3D" : "Tryb 2D";
  $("#verdict").textContent = progress.isSolved(ch.id) ? "Rozwiązane wcześniej. Możesz próbować dalej." : "";
  $("#verdict").className = "verdict" + (progress.isSolved(ch.id) ? " pass" : "");
  runner.reset();
  mode = ch.mode;
  editor.value = progress.code(ch.id) ?? "; Twój program\n";
  const ghost = targetOf(ch);
  view2d.ghost = ghost;
  updateModeUI();
  const ready = ch.mode === "3d" ? ensure3D() : Promise.resolve(null);
  void ready.then(() => {
    view3d?.setGhost(ghost);
    updateModeUI();
    runProgram({ animate: false, fit: true });
  });
}

$("#check-btn").addEventListener("click", () => {
  if (context.kind !== "challenge") return;
  const ch = context.challenge;
  const res = checkChallenge(ch, editor.value);
  progress.record(ch.id, editor.value, res.pass);
  const v = $("#verdict");
  v.className = "verdict " + (res.pass ? "pass" : "fail");
  v.textContent = (res.pass ? "Zaliczone. " : "Jeszcze nie. ") + res.reason;
  updateSolved();
  runProgram();
});

function updateSolved() {
  $("#solved-count").textContent = `${progress.solvedCount}/${CHALLENGES.length}`;
  $("#solved-count").setAttribute("aria-label", `rozwiązane ${progress.solvedCount} z ${CHALLENGES.length}`);
  renderChallengeList();
}

// ---------- pages ----------

function cell(segs: Segment[], m: Mode, dashed: boolean) {
  const c = document.createElement("canvas");
  c.className = "thumb";
  c.setAttribute("aria-hidden", "true");
  c.dataset.mode = m;
  c.dataset.dashed = String(dashed);
  (c as HTMLCanvasElement & { segs?: Segment[] }).segs = segs;
  return c;
}

function renderExamples() {
  for (const m of ["2d", "3d"] as Mode[]) {
    const ul = $(`#ex-${m}`);
    ul.innerHTML = "";
    for (const ex of EXAMPLES.filter((e) => e.mode === m)) {
      const li = document.createElement("li");
      li.className = "cell";
      li.append(cell(run(ex.source, ex.mode).segments, ex.mode, false));
      const body = document.createElement("div");
      body.className = "cell-body";
      body.innerHTML = `<h3></h3><p></p>`;
      body.querySelector("h3")!.textContent = ex.title;
      body.querySelector("p")!.textContent = ex.blurb;
      const b = document.createElement("button");
      b.type = "button";
      b.className = "btn btn-small cell-action";
      b.textContent = "Otwórz w studiu";
      b.setAttribute("aria-label", `Otwórz przykład ${ex.title} w studiu`);
      b.addEventListener("click", () => loadExample(ex));
      body.append(b);
      li.append(body);
      ul.append(li);
    }
  }
}

function renderChallengeList() {
  const ol = $("#ch-list");
  ol.innerHTML = "";
  CHALLENGES.forEach((ch) => {
    const li = document.createElement("li");
    li.className = "cell" + (progress.isSolved(ch.id) ? " solved" : "");
    li.append(cell(targetOf(ch), ch.mode, true));
    const body = document.createElement("div");
    body.className = "cell-body";
    const solved = progress.isSolved(ch.id);
    body.innerHTML = `<h3><a></a></h3><p></p><span class="cell-meta"></span>`;
    const a = body.querySelector("a")!;
    a.href = `#/zadania/${ch.id}`;
    a.textContent = ch.title;
    body.querySelector("p")!.textContent = ch.task;
    body.querySelector(".cell-meta")!.innerHTML = `${ch.mode.toUpperCase()} · ${solved ? `<svg class="i"><use href="#i-check"/></svg>Rozwiązane` : "Do zrobienia"}`;
    li.append(body);
    ol.append(li);
  });
  renderThumbs();
}

function renderThumbs() {
  requestAnimationFrame(() =>
    document.querySelectorAll<HTMLCanvasElement & { segs?: Segment[] }>("canvas.thumb").forEach((c) => {
      if (c.offsetParent) paintThumb(c, c.segs ?? [], c.dataset.mode as Mode, c.dataset.dashed === "true");
    }),
  );
}

$("#sciaga").innerHTML = referenceHTML();
$("#sciaga").addEventListener("click", (e) => {
  const b = (e.target as HTMLElement).closest<HTMLButtonElement>("[data-try]");
  if (!b) return;
  location.hash = "#/";
  void loadIntoDraft(b.dataset.try!, b.dataset.mode as Mode, { animate: true });
});
$("#sciaga").addEventListener("click", (e) => {
  const a = (e.target as HTMLElement).closest<HTMLAnchorElement>(".toc a");
  if (!a) return;
  // in-page anchors must not disturb the hash router
  e.preventDefault();
  document.getElementById(a.getAttribute("href")!.slice(1))?.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
  document.getElementById(a.getAttribute("href")!.slice(1))?.querySelector("h2")?.setAttribute("tabindex", "-1");
});

// ---------- routing ----------

const TITLES: Record<string, string> = { studio: "Studio", przyklady: "Przykłady", zadania: "Zadania", sciaga: "Ściąga" };

async function route() {
  const hash = location.hash || "#/";
  const shared = readPermalink(hash);
  if (shared) {
    history.replaceState(null, "", location.href.split("#")[0] + "#/");
    show("studio");
    await loadIntoDraft(shared.source, shared.mode, { animate: true });
    toast("Otwarto program z linku.");
    return;
  }
  const m = /^#\/(przyklady|zadania|sciaga)?(?:\/([\w-]+))?\/?$/.exec(hash);
  const page = m?.[1] ?? "studio";
  if (page === "zadania" && m?.[2]) {
    const ch = CHALLENGES.find((c) => c.id === m[2]);
    if (ch) {
      show("studio", "zadania");
      openChallenge(ch);
      document.title = `${ch.title} — zadanie — Logomocja`;
      return;
    }
  }
  if (page === "studio" && context.kind === "challenge") {
    enterDraft();
    void setMode(workspace.mode);
  }
  show(page);
}

function show(page: string, navPage = page) {
  for (const id of ["studio", "przyklady", "zadania", "sciaga"]) $(`#${id}`).hidden = id !== page;
  document.querySelectorAll<HTMLAnchorElement>(".mainnav a").forEach((a) => {
    if (a.dataset.route === navPage) a.setAttribute("aria-current", "page");
    else a.removeAttribute("aria-current");
  });
  document.body.dataset.page = page;
  $("#mode-switch").hidden = page !== "studio";
  document.title = `${TITLES[navPage] ?? "Studio"} — Logomocja`;
  if (page !== "studio") { runner.pause(); window.scrollTo(0, 0); renderThumbs(); }
  else { view2d.invalidate(); view3d?.invalidate(); }
}

window.addEventListener("hashchange", () => void route());

// ---------- testing hook ----------

const nextFrame = () => new Promise<void>((r) => requestAnimationFrame(() => r()));

declare global {
  interface Window {
    logomocja: {
      version: string;
      run(source: string, mode: Mode): RunResult;
      open(source: string, mode: Mode): Promise<RunResult>;
    };
  }
}

window.logomocja = {
  version: VERSION,
  run: (source, m) => run(String(source), m === "3d" ? "3d" : "2d"),
  async open(source, m) {
    const md: Mode = m === "3d" ? "3d" : "2d";
    if (location.hash !== "#/" && location.hash !== "") {
      history.replaceState(null, "", location.href.split("#")[0] + "#/");
    }
    show("studio");
    enterDraft();
    await loadIntoDraft(String(source), md, { animate: false });
    activeView().fit();
    await nextFrame();
    activeView().draw();
    await nextFrame();
    const s = runner.state;
    return {
      segments: s.segments.map((x) => ({ from: [...x.from], to: [...x.to], color: x.color, width: x.width })),
      error: s.error ? { ...s.error } : null,
    } as RunResult;
  },
};

// ---------- start ----------

setTheme(storedTheme());
renderExamples();
updateSolved();
editor.value = workspace.source;
updateModeUI();
void (async () => {
  if (readPermalink(location.hash)) { await route(); return; }
  await route();
  if (context.kind === "draft") await setMode(workspace.mode);
})();

