/* Logomocja — the stencil-ruler world: paper ground, green translucent plastic, copper turtle. */

:root {
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, sans-serif;
  --font-code: ui-monospace, "Cascadia Mono", "JetBrains Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --paper: #f2f4f0;
  --surface: #ffffff;
  --sunken: #eaeee9;
  --ink: #16201b;
  --ink-2: #4a5852;
  --ink-3: #6a7871;
  --line: #d3dbd6;
  --line-strong: #b4c2bb;
  --green: #16866a;
  --green-strong: #0f6b54;
  --green-ink: #0d5e4a;
  --plastic: rgba(22, 134, 106, 0.09);
  --plastic-2: rgba(22, 134, 106, 0.16);
  --copper: #a85a24;
  --danger: #b3261e;
  --danger-bg: #fbeceb;
  --on-green: #ffffff;
  --shell: #16866a;
  --shell-ink: #ffffff;
  --shell-ink-2: rgba(255, 255, 255, 0.78);
  --shell-plastic: rgba(255, 255, 255, 0.14);

  --canvas: #fbfcfa;
  --grid: rgba(22, 134, 106, 0.17);
  --grid-minor: rgba(22, 134, 106, 0.07);
  --axis: #16866a;
  --ruler: #e1eee8;
  --ruler-edge: #a9cbbb;
  --ruler-ink: #2c5c4d;
  --turtle: #c1763d;
  --ghost: rgba(193, 118, 61, 0.42);

  --t-command: #0f6b54;
  --t-keyword: #8a3ea8;
  --t-proc: #1f5fa3;
  --t-name: #16201b;
  --t-number: #a8501e;
  --t-string: #8a5a00;
  --t-comment: #6a7871;
  --t-bracket: #4a5852;

  --radius: 10px;
  --radius-s: 7px;
  --lh: 22px;
  --shadow: 0 1px 2px rgba(20, 40, 30, 0.06), 0 6px 18px rgba(20, 40, 30, 0.07);
  --focus: 0 0 0 2px var(--surface), 0 0 0 4px var(--green);
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  color-scheme: light;
}

:root[data-theme="dark"] {
  --paper: #0e1412;
  --surface: #151d1a;
  --sunken: #111816;
  --ink: #e3ebe7;
  --ink-2: #a9b8b1;
  --ink-3: #8a9a93;
  --line: #27332f;
  --line-strong: #3a4a44;
  --green: #3fbf96;
  --green-strong: #5fd4ad;
  --green-ink: #7fe0bf;
  --plastic: rgba(63, 191, 150, 0.1);
  --plastic-2: rgba(63, 191, 150, 0.18);
  --copper: #eda36b;
  --danger: #ff9a90;
  --danger-bg: #3a1714;
  --on-green: #06231a;
  --shell: #0f3a2e;
  --shell-ink: #e9f6f0;
  --shell-ink-2: rgba(233, 246, 240, 0.74);
  --shell-plastic: rgba(255, 255, 255, 0.09);

  --canvas: #111a17;
  --grid: rgba(63, 191, 150, 0.15);
  --grid-minor: rgba(63, 191, 150, 0.06);
  --axis: #3fbf96;
  --ruler: #15302a;
  --ruler-edge: #285246;
  --ruler-ink: #9fd8c2;
  --turtle: #eda36b;
  --ghost: rgba(237, 163, 107, 0.5);

  --t-command: #5fd4ad;
  --t-keyword: #d6a2ef;
  --t-proc: #8ec1ff;
  --t-name: #e3ebe7;
  --t-number: #f2a774;
  --t-string: #e8c46a;
  --t-comment: #8a9a93;
  --t-bracket: #a9b8b1;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px rgba(0, 0, 0, 0.28);
  color-scheme: dark;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font: 15px/1.5 var(--font-ui);
  color: var(--ink);
  background: var(--paper);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}
::selection { background: var(--plastic-2); color: inherit; }
.ed-input::selection { background: var(--plastic-2); color: transparent; }
* { scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--line-strong); border-radius: 10px; border: 2px solid transparent; background-clip: padding-box; }
a { color: var(--green-ink); text-underline-offset: 0.2em; text-decoration-thickness: 1px; }
a:hover { text-decoration-thickness: 2px; }
:focus-visible { outline: none; box-shadow: var(--focus); border-radius: var(--radius-s); }
[hidden] { display: none !important; }
code, kbd, pre { font-family: var(--font-code); }
code { font-size: 0.92em; }
kbd {
  font-size: 0.82em; padding: 1px 6px; border-radius: 5px;
  border: 1px solid var(--line-strong); border-bottom-width: 2px; background: var(--surface);
}

.skip {
  position: absolute; left: 12px; top: -48px; z-index: 50; padding: 8px 14px;
  background: var(--surface); color: var(--ink); border-radius: var(--radius-s); box-shadow: var(--shadow);
}
.skip:focus { top: 8px; }

/* icons: one stroke family */
.i { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
#i-play path, .i use[href="#i-play"] { fill: currentColor; }
.i .fill, #i-theme .fill { fill: currentColor; }

/* ---------- top bar: the green stencil strip ---------- */

.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 20px;
  min-height: 56px; padding: 0 16px;
  padding-left: max(16px, env(safe-area-inset-left)); padding-right: max(16px, env(safe-area-inset-right));
  background: var(--shell); color: var(--shell-ink);
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  color: inherit; text-decoration: none; font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
}
.brand-mark { width: 30px; height: 30px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.brand-mark .brand-turtle { fill: #f2b98a; stroke: none; }
.mainnav { display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; }
.mainnav a {
  color: var(--shell-ink-2); text-decoration: none; padding: 7px 12px; border-radius: 8px;
  font-weight: 550; white-space: nowrap; transition: background 160ms var(--ease), color 160ms var(--ease);
}
.mainnav a:hover { color: var(--shell-ink); background: var(--shell-plastic); }
.mainnav a[aria-current="page"] { color: var(--shell-ink); background: var(--shell-plastic); box-shadow: inset 0 -2px 0 #f2b98a; }
.mainnav .count { font-variant-numeric: tabular-nums; font-size: 12px; opacity: 0.85; margin-left: 2px; }
.topbar :focus-visible { box-shadow: 0 0 0 2px var(--shell), 0 0 0 4px #ffffff; }
.topbar-end { margin-left: auto; display: flex; align-items: center; gap: 10px; }

.segmented {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: rgba(0, 0, 0, 0.16);
}
.segmented button {
  font: 600 13px/1 var(--font-ui); letter-spacing: 0.02em; color: var(--shell-ink-2);
  border: 0; background: transparent; padding: 7px 13px; border-radius: 7px; cursor: pointer; min-height: 30px;
}
.segmented button[aria-checked="true"] { background: var(--shell-ink); color: var(--shell); }
.segmented button:disabled { opacity: 0.4; cursor: not-allowed; }
.topbar .btn-icon { color: var(--shell-ink); }
.topbar .btn-icon:hover { background: var(--shell-plastic); }

/* ---------- buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  min-height: 38px; padding: 0 14px;
  font: 600 14px/1 var(--font-ui); color: var(--ink);
  background: var(--surface); border: 1px solid var(--line-strong); border-radius: 9px;
  cursor: pointer; white-space: nowrap;
  transition: background 140ms var(--ease), border-color 140ms var(--ease), transform 140ms var(--ease);
}
.btn:hover { background: var(--plastic); border-color: var(--green); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; background: var(--surface); border-color: var(--line); transform: none; }
.btn-primary { background: var(--green); border-color: var(--green); color: var(--on-green); }
.btn-primary:hover { background: var(--green-strong); border-color: var(--green-strong); }
.btn-small { min-height: 32px; padding: 0 11px; font-size: 13px; }
.btn-quiet { border-color: transparent; background: transparent; color: var(--green-ink); padding: 0 8px; }
.btn-quiet:hover { background: var(--plastic); border-color: transparent; }
.btn-icon {
  display: inline-grid; place-items: center; width: 38px; height: 38px; padding: 0;
  border: 0; border-radius: 9px; background: transparent; color: var(--ink-2); cursor: pointer;
  transition: background 140ms var(--ease), color 140ms var(--ease);
}
.btn-icon:hover { background: var(--plastic); color: var(--ink); }
.btn-icon[aria-pressed="true"], .btn-icon[aria-expanded="true"] { color: var(--green-ink); background: var(--plastic); }
.btn-icon.btn-small { width: 30px; height: 30px; }

/* ---------- studio ---------- */

main { flex: 1; display: flex; flex-direction: column; min-height: 0; }
main:focus { outline: none; }
.studio {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: minmax(340px, 36rem) minmax(0, 1fr);
  height: calc(100dvh - 56px);
}
.pane-code {
  display: flex; flex-direction: column; gap: 10px; min-height: 0;
  padding: 14px 16px 12px; border-right: 1px solid var(--line); background: var(--paper);
  overflow-y: auto;
}
.code-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.code-title { margin: 0; font-size: 14px; font-weight: 650; color: var(--ink-2); letter-spacing: 0; }
.file-tools { display: flex; gap: 2px; }

.share-panel {
  display: grid; gap: 6px; padding: 10px 12px; border-radius: var(--radius);
  background: var(--plastic); font-size: 13px; color: var(--ink-2);
}
.share-row { display: flex; gap: 6px; }
.share-row input {
  flex: 1; min-width: 0; font: 13px var(--font-code); color: var(--ink);
  padding: 6px 9px; border-radius: 7px; border: 1px solid var(--line-strong); background: var(--surface);
}

/* editor */
.editor {
  position: relative; flex: 1 1 auto; min-height: 14rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
}
.editor:focus-within { border-color: var(--green); }
.ed-scroll { position: absolute; inset: 0; overflow: auto; }
.ed-inner { display: grid; grid-template-columns: 3rem max-content; min-width: 100%; min-height: 100%; padding: 10px 0; }
.ed-gutter {
  position: sticky; left: 0; z-index: 2;
  font: 13px/var(--lh) var(--font-code); color: var(--ink-3); text-align: right;
  font-variant-numeric: tabular-nums; background: var(--surface); padding-right: 10px; user-select: none;
  min-height: 100%;
}
.ed-gutter span { display: block; }
.ed-code { position: relative; min-width: 100%; }
.ed-hl, .ed-input {
  margin: 0; padding: 0 20px 0 6px; border: 0;
  font: 14px/var(--lh) var(--font-code); tab-size: 2; white-space: pre; letter-spacing: 0;
}
.ed-hl { color: var(--ink); pointer-events: none; min-height: 100%; }
.ed-input {
  position: absolute; inset: 0; width: 100%; height: 100%; resize: none; overflow: hidden;
  background: transparent; color: transparent; caret-color: var(--ink); outline: none; z-index: 1;
}
.ed-input:focus-visible { box-shadow: none; }
.ed-band, .ed-err-row {
  position: absolute; left: 0; right: 0; height: var(--lh);
  top: calc(var(--line) * var(--lh));
}
.ed-band { background: var(--plastic-2); box-shadow: inset 3px 0 0 var(--turtle); transition: top 90ms linear; }
.ed-err-row { background: var(--danger-bg); }
.ed-err-mark {
  position: absolute; z-index: 1; pointer-events: none;
  top: calc(var(--line) * var(--lh)); height: var(--lh);
  left: calc(6px + var(--col) * 1ch); width: calc(var(--len) * 1ch);
  font: 14px/var(--lh) var(--font-code);
  border-bottom: 2px solid var(--danger);
}
.ed-bubble {
  position: absolute; z-index: 3; pointer-events: none;
  top: calc((var(--line) + 1) * var(--lh) + 3px);
  left: max(4px, calc(var(--col) * 1ch - 8px));
  width: max-content; max-width: min(30rem, 80vw); white-space: normal;
  font: 13px/1.45 var(--font-ui); padding: 7px 10px; border-radius: 8px;
  background: var(--danger); color: #fff; box-shadow: var(--shadow);
}
:root[data-theme="dark"] .ed-bubble { color: #2a0b08; }
.ed-bubble::before {
  content: ""; position: absolute; top: -5px; left: 12px; width: 10px; height: 10px;
  background: inherit; transform: rotate(45deg); border-radius: 2px;
}
.ed-bubble strong { font-weight: 700; }
.t-command { color: var(--t-command); font-weight: 600; }
.t-keyword { color: var(--t-keyword); font-weight: 600; }
.t-proc { color: var(--t-proc); }
.t-name { color: var(--t-name); }
.t-value { color: var(--t-proc); font-style: italic; }
.t-number { color: var(--t-number); }
.t-string { color: var(--t-string); }
.t-string::before {
  content: ""; display: inline-block; width: 0.7em; height: 0.7em; margin-right: 0.25em;
  border-radius: 3px; background: var(--swatch); vertical-align: -0.04em; box-shadow: inset 0 0 0 1px rgba(0,0,0,.15);
  margin-left: -0.95em;
}
.t-comment { color: var(--t-comment); font-style: italic; }
.t-bracket { color: var(--t-bracket); font-weight: 700; }
.t-paren, .t-op { color: var(--t-bracket); }
.t-bad { color: var(--danger); }

/* transport */
.transport { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.transport .btn { min-width: 0; }
.studio[data-status="running"] #run-btn { background: var(--green-strong); }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--ink-2); font-weight: 550; }
input[type="range"] { accent-color: var(--green); width: 110px; height: 28px; }
.status {
  margin: 0; min-height: 1.5em; font-size: 13.5px; color: var(--ink-2); font-variant-numeric: tabular-nums;
}
.studio[data-status="error"] .status { color: var(--danger); font-weight: 550; }
.shortcuts { font-size: 13px; color: var(--ink-2); }
.shortcuts summary { cursor: pointer; font-weight: 600; width: max-content; border-radius: 6px; padding: 2px 4px; margin-left: -4px; }
.shortcuts dl { display: grid; gap: 6px; margin: 10px 0 6px; }
.shortcuts dl div { display: grid; grid-template-columns: minmax(11rem, auto) 1fr; gap: 10px; align-items: baseline; }
.shortcuts dt, .shortcuts dd { margin: 0; }
.shortcuts p { margin: 4px 0 0; }

/* view */
.pane-view { position: relative; min-width: 0; min-height: 0; background: var(--canvas); }
.view-stage { position: absolute; inset: 0; }
.view-stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; }
.view-stage canvas.grabbing { cursor: grabbing; }
.view-stage canvas:focus-visible { box-shadow: inset 0 0 0 2px var(--green); border-radius: 0; }
.view-tools {
  position: absolute; right: 12px; bottom: 12px; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 2px;
  padding: 4px; border-radius: 12px; background: var(--surface); box-shadow: var(--shadow);
  max-width: calc(100% - 24px);
}
.tool-sep { width: 1px; align-self: stretch; margin: 6px 3px; background: var(--line); }
.view-stage[data-flat="true"] .only-3d, .view-stage[data-mode="3d"]:not([data-flat="true"]) .only-2d { display: none; }
.readout {
  position: absolute; left: 34px; bottom: 14px; pointer-events: none;
  font: 12px/1.3 var(--font-code); color: var(--ruler-ink); white-space: pre; font-variant-numeric: tabular-nums;
  padding: 5px 8px; border-radius: 7px; background: color-mix(in srgb, var(--canvas) 82%, transparent);
  max-width: calc(100% - 300px); overflow: hidden; text-overflow: ellipsis;
}
.view-stage[data-flat="false"] .readout { left: 12px; }
.view-note {
  position: absolute; left: 34px; right: 12px; top: 34px; z-index: 2; max-width: 40rem;
  padding: 10px 12px; border-radius: var(--radius); font-size: 13.5px;
  background: var(--surface); color: var(--ink); box-shadow: var(--shadow);
}

/* challenge task panel */
.task {
  display: grid; gap: 8px; padding: 14px; border-radius: var(--radius);
  background: var(--plastic); border: 1px solid var(--plastic-2);
}
.task-head { display: flex; justify-content: space-between; align-items: center; }
.task .back { display: inline-flex; align-items: center; gap: 2px; font-size: 13px; font-weight: 600; text-decoration: none; }
.task .back .i { width: 16px; height: 16px; }
.mode-tag { font-size: 12px; font-weight: 650; color: var(--green-ink); }
.task h1 { margin: 2px 0 0; font-size: 20px; line-height: 1.25; letter-spacing: -0.01em; }
.task p { margin: 0; }
.hint summary { cursor: pointer; font-weight: 600; color: var(--green-ink); width: max-content; font-size: 14px; border-radius: 6px; }
.hint p { margin-top: 6px; color: var(--ink-2); }
.task-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.verdict { margin: 0; font-size: 14px; flex: 1 1 14rem; }
.verdict.pass { color: var(--green-ink); font-weight: 600; }
.verdict.fail { color: var(--danger); font-weight: 550; }

/* ---------- pages ---------- */

.page { width: 100%; max-width: 74rem; margin: 0 auto; padding: 36px 24px 72px; }
.page-head { margin-bottom: 28px; }
.page-head h1 { margin: 0 0 8px; font-size: clamp(26px, 3.2vw, 34px); line-height: 1.15; letter-spacing: -0.02em; text-wrap: balance; }
.lede { margin: 0; max-width: 62ch; color: var(--ink-2); font-size: 16px; }
.group-h { font-size: 15px; font-weight: 650; color: var(--ink-2); margin: 32px 0 12px; }
.cells {
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); gap: 14px;
}
.cell {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--surface); border-radius: 12px; box-shadow: var(--shadow);
}
.cell .thumb { width: 100%; aspect-ratio: 4 / 3; display: block; border-bottom: 1px solid var(--line); }
.cell-body { display: flex; flex-direction: column; gap: 4px; padding: 12px 14px 14px; flex: 1; }
.cell-body h3 { margin: 0; font-size: 16px; letter-spacing: -0.005em; }
.cell-body h3 a { color: var(--ink); text-decoration: none; }
.cell-body h3 a::after { content: ""; position: absolute; inset: 0; }
.cell-body h3 a:hover { color: var(--green-ink); }
.cell-body p { margin: 0; color: var(--ink-2); font-size: 14px; }
.cell-action { margin-top: auto; align-self: flex-start; margin-top: 10px; }
#ch-list .cell { position: relative; }
#ch-list .cell:focus-within { box-shadow: var(--shadow), var(--focus); }
#ch-list .cell-body h3 a:focus-visible { box-shadow: none; }
.cell-meta { margin-top: auto; padding-top: 8px; display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 600; color: var(--ink-3); }
.cell.solved .cell-meta { color: var(--green-ink); }
.cell-meta .i { width: 16px; height: 16px; stroke-width: 2.4; }

/* reference (Read surface inside the app) */
.page-read { max-width: 60rem; }
.toc { display: flex; flex-wrap: wrap; gap: 4px 6px; margin-top: 18px; }
.toc a {
  font-size: 14px; font-weight: 550; padding: 5px 10px; border-radius: 8px; text-decoration: none;
  background: var(--plastic); color: var(--green-ink);
}
.toc a:hover { background: var(--plastic-2); }
.ref-section { margin-top: 44px; scroll-margin-top: 72px; }
.ref-section h2 { font-size: 22px; letter-spacing: -0.01em; margin: 0 0 12px; outline: none; }
.ref-section > p, .ref-section li { max-width: 70ch; }
.ref-section li { margin-bottom: 6px; }
.ref-list { margin: 0; display: grid; gap: 0; border-top: 1px solid var(--line); }
.ref-entry { display: grid; grid-template-columns: minmax(12rem, 16rem) 1fr; gap: 8px 24px; padding: 16px 0; border-bottom: 1px solid var(--line); }
.ref-entry dt { display: flex; flex-direction: column; gap: 4px; }
.ref-entry dt .cmd { font-weight: 700; color: var(--t-command); font-size: 15px; }
.ref-en { font: 13px var(--font-code); color: var(--ink-3); }
.ref-entry dd { margin: 0; }
.ref-entry dd p { margin: 0 0 6px; max-width: 64ch; }
.ref-arg { font-size: 13.5px; color: var(--ink-2); }
.ref-example { display: flex; align-items: flex-start; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
pre.code {
  margin: 0; padding: 9px 12px; border-radius: 8px; background: var(--sunken);
  font-size: 13.5px; line-height: 1.55; overflow-x: auto; flex: 0 1 auto; max-width: 100%;
}
.limits { border-collapse: collapse; width: 100%; max-width: 46rem; font-size: 14px; }
.limits caption { text-align: left; color: var(--ink-2); padding-bottom: 8px; }
.limits th, .limits td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.limits th { font-weight: 500; }
.limits td { font-variant-numeric: tabular-nums; font-weight: 650; white-space: nowrap; }

/* toast */
.toast {
  position: fixed; left: 50%; bottom: max(16px, env(safe-area-inset-bottom)); z-index: 40;
  transform: translateX(-50%); display: flex; align-items: center; gap: 10px;
  max-width: calc(100vw - 24px); padding: 8px 8px 8px 16px; border-radius: 12px;
  background: var(--ink); color: var(--paper); box-shadow: var(--shadow); font-size: 14px;
  animation: toast-in 320ms var(--ease);
}
.toast .btn { background: transparent; color: inherit; border-color: color-mix(in srgb, var(--paper) 40%, transparent); }
.toast .btn-icon { color: inherit; }
.toast .btn-icon:hover, .toast .btn:hover { background: color-mix(in srgb, var(--paper) 14%, transparent); }
@keyframes toast-in { from { opacity: 0; transform: translate(-50%, 8px); filter: blur(3px); } }

/* ---------- small screens ---------- */

@media (max-width: 880px) {
  .studio { display: flex; flex-direction: column; height: auto; }
  .pane-view { order: -1; height: min(52vh, 32rem); min-height: 260px; flex: none; }
  .pane-code { border-right: 0; overflow: visible; padding: 12px; }
  .editor { flex: none; height: 46vh; min-height: 16rem; }
  .readout { display: none; }
  .view-note { left: 12px; }
}
@media (max-width: 600px) {
  .topbar { flex-wrap: wrap; gap: 6px 12px; padding-top: 6px; padding-bottom: 6px; }
  .mainnav { order: 3; width: 100%; margin: 0 -8px; }
  .mainnav a { padding: 6px 10px; }
  .transport .btn span { display: none; }
  .transport .btn { width: 44px; padding: 0; min-height: 44px; }
  .btn-icon { width: 44px; height: 44px; }
  .speed { margin-left: 0; flex: 1; }
  .speed input { flex: 1; }
  .page { padding: 24px 16px 56px; }
  .ref-entry { grid-template-columns: 1fr; }
  .shortcuts dl div { grid-template-columns: 1fr; gap: 2px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; }
}

tool_use_result.content:
/* Logomocja — the stencil-ruler world: paper ground, green translucent plastic, copper turtle. */

:root {
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, sans-serif;
  --font-code: ui-monospace, "Cascadia Mono", "JetBrains Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --paper: #f2f4f0;
  --surface: #ffffff;
  --sunken: #eaeee9;
  --ink: #16201b;
  --ink-2: #4a5852;
  --ink-3: #6a7871;
  --line: #d3dbd6;
  --line-strong: #b4c2bb;
  --green: #16866a;
  --green-strong: #0f6b54;
  --green-ink: #0d5e4a;
  --plastic: rgba(22, 134, 106, 0.09);
  --plastic-2: rgba(22, 134, 106, 0.16);
  --copper: #a85a24;
  --danger: #b3261e;
  --danger-bg: #fbeceb;
  --on-green: #ffffff;
  --shell: #16866a;
  --shell-ink: #ffffff;
  --shell-ink-2: rgba(255, 255, 255, 0.78);
  --shell-plastic: rgba(255, 255, 255, 0.14);

  --canvas: #fbfcfa;
  --grid: rgba(22, 134, 106, 0.17);
  --grid-minor: rgba(22, 134, 106, 0.07);
  --axis: #16866a;
  --ruler: #e1eee8;
  --ruler-edge: #a9cbbb;
  --ruler-ink: #2c5c4d;
  --turtle: #c1763d;
  --ghost: rgba(193, 118, 61, 0.42);

  --t-command: #0f6b54;
  --t-keyword: #8a3ea8;
  --t-proc: #1f5fa3;
  --t-name: #16201b;
  --t-number: #a8501e;
  --t-string: #8a5a00;
  --t-comment: #6a7871;
  --t-bracket: #4a5852;

  --radius: 10px;
  --radius-s: 7px;
  --lh: 22px;
  --shadow: 0 1px 2px rgba(20, 40, 30, 0.06), 0 6px 18px rgba(20, 40, 30, 0.07);
  --focus: 0 0 0 2px var(--surface), 0 0 0 4px var(--green);
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  color-scheme: light;
}

:root[data-theme="dark"] {
  --paper: #0e1412;
  --surface: #151d1a;
  --sunken: #111816;
  --ink: #e3ebe7;
  --ink-2: #a9b8b1;
  --ink-3: #8a9a93;
  --line: #27332f;
  --line-strong: #3a4a44;
  --green: #3fbf96;
  --green-strong: #5fd4ad;
  --green-ink: #7fe0bf;
  --plastic: rgba(63, 191, 150, 0.1);
  --plastic-2: rgba(63, 191, 150, 0.18);
  --copper: #eda36b;
  --danger: #ff9a90;
  --danger-bg: #3a1714;
  --on-green: #06231a;
  --shell: #0f3a2e;
  --shell-ink: #e9f6f0;
  --shell-ink-2: rgba(233, 246, 240, 0.74);
  --shell-plastic: rgba(255, 255, 255, 0.09);

  --canvas: #111a17;
  --grid: rgba(63, 191, 150, 0.15);
  --grid-minor: rgba(63, 191, 150, 0.06);
  --axis: #3fbf96;
  --ruler: #15302a;
  --ruler-edge: #285246;
  --ruler-ink: #9fd8c2;
  --turtle: #eda36b;
  --ghost: rgba(237, 163, 107, 0.5);

  --t-command: #5fd4ad;
  --t-keyword: #d6a2ef;
  --t-proc: #8ec1ff;
  --t-name: #e3ebe7;
  --t-number: #f2a774;
  --t-string: #e8c46a;
  --t-comment: #8a9a93;
  --t-bracket: #a9b8b1;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px rgba(0, 0, 0, 0.28);
  color-scheme: dark;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font: 15px/1.5 var(--font-ui);
  color: var(--ink);
  background: var(--paper);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}
::selection { background: var(--plastic-2); color: inherit; }
.ed-input::selection { background: var(--plastic-2); color: transparent; }
* { scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--line-strong); border-radius: 10px; border: 2px solid transparent; background-clip: padding-box; }
a { color: var(--green-ink); text-underline-offset: 0.2em; text-decoration-thickness: 1px; }
a:hover { text-decoration-thickness: 2px; }
:focus-visible { outline: none; box-shadow: var(--focus); border-radius: var(--radius-s); }
[hidden] { display: none !important; }
code, kbd, pre { font-family: var(--font-code); }
code { font-size: 0.92em; }
kbd {
  font-size: 0.82em; padding: 1px 6px; border-radius: 5px;
  border: 1px solid var(--line-strong); border-bottom-width: 2px; background: var(--surface);
}

.skip {
  position: absolute; left: 12px; top: -48px; z-index: 50; padding: 8px 14px;
  background: var(--surface); color: var(--ink); border-radius: var(--radius-s); box-shadow: var(--shadow);
}
.skip:focus { top: 8px; }

/* icons: one stroke family */
.i { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
#i-play path, .i use[href="#i-play"] { fill: currentColor; }
.i .fill, #i-theme .fill { fill: currentColor; }

/* ---------- top bar: the green stencil strip ---------- */

.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 20px;
  min-height: 56px; padding: 0 16px;
  padding-left: max(16px, env(safe-area-inset-left)); padding-right: max(16px, env(safe-area-inset-right));
  background: var(--shell); color: var(--shell-ink);
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  color: inherit; text-decoration: none; font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
}
.brand-mark { width: 30px; height: 30px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.brand-mark .brand-turtle { fill: #f2b98a; stroke: none; }
.mainnav { display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; }
.mainnav a {
  color: var(--shell-ink-2); text-decoration: none; padding: 7px 12px; border-radius: 8px;
  font-weight: 550; white-space: nowrap; transition: background 160ms var(--ease), color 160ms var(--ease);
}
.mainnav a:hover { color: var(--shell-ink); background: var(--shell-plastic); }
.mainnav a[aria-current="page"] { color: var(--shell-ink); background: var(--shell-plastic); box-shadow: inset 0 -2px 0 #f2b98a; }
.mainnav .count { font-variant-numeric: tabular-nums; font-size: 12px; opacity: 0.85; margin-left: 2px; }
.topbar :focus-visible { box-shadow: 0 0 0 2px var(--shell), 0 0 0 4px #ffffff; }
.topbar-end { margin-left: auto; display: flex; align-items: center; gap: 10px; }

.segmented {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: rgba(0, 0, 0, 0.16);
}
.segmented button {
  font: 600 13px/1 var(--font-ui); letter-spacing: 0.02em; color: var(--shell-ink-2);
  border: 0; background: transparent; padding: 7px 13px; border-radius: 7px; cursor: pointer; min-height: 30px;
}
.segmented button[aria-checked="true"] { background: var(--shell-ink); color: var(--shell); }
.segmented button:disabled { opacity: 0.4; cursor: not-allowed; }
.topbar .btn-icon { color: var(--shell-ink); }
.topbar .btn-icon:hover { background: var(--shell-plastic); }

/* ---------- buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  min-height: 38px; padding: 0 14px;
  font: 600 14px/1 var(--font-ui); color: var(--ink);
  background: var(--surface); border: 1px solid var(--line-strong); border-radius: 9px;
  cursor: pointer; white-space: nowrap;
  transition: background 140ms var(--ease), border-color 140ms var(--ease), transform 140ms var(--ease);
}
.btn:hover { background: var(--plastic); border-color: var(--green); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; background: var(--surface); border-color: var(--line); transform: none; }
.btn-primary { background: var(--green); border-color: var(--green); color: var(--on-green); }
.btn-primary:hover { background: var(--green-strong); border-color: var(--green-strong); }
.btn-small { min-height: 32px; padding: 0 11px; font-size: 13px; }
.btn-quiet { border-color: transparent; background: transparent; color: var(--green-ink); padding: 0 8px; }
.btn-quiet:hover { background: var(--plastic); border-color: transparent; }
.btn-icon {
  display: inline-grid; place-items: center; width: 38px; height: 38px; padding: 0;
  border: 0; border-radius: 9px; background: transparent; color: var(--ink-2); cursor: pointer;
  transition: background 140ms var(--ease), color 140ms var(--ease);
}
.btn-icon:hover { background: var(--plastic); color: var(--ink); }
.btn-icon[aria-pressed="true"], .btn-icon[aria-expanded="true"] { color: var(--green-ink); background: var(--plastic); }
.btn-icon.btn-small { width: 30px; height: 30px; }

/* ---------- studio ---------- */

main { flex: 1; display: flex; flex-direction: column; min-height: 0; }
main:focus { outline: none; }
.studio {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: minmax(340px, 36rem) minmax(0, 1fr);
  height: calc(100dvh - 56px);
}
.pane-code {
  display: flex; flex-direction: column; gap: 10px; min-height: 0;
  padding: 14px 16px 12px; border-right: 1px solid var(--line); background: var(--paper);
  overflow-y: auto;
}
.code-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.code-title { margin: 0; font-size: 14px; font-weight: 650; color: var(--ink-2); letter-spacing: 0; }
.file-tools { display: flex; gap: 2px; }

.share-panel {
  display: grid; gap: 6px; padding: 10px 12px; border-radius: var(--radius);
  background: var(--plastic); font-size: 13px; color: var(--ink-2);
}
.share-row { display: flex; gap: 6px; }
.share-row input {
  flex: 1; min-width: 0; font: 13px var(--font-code); color: var(--ink);
  padding: 6px 9px; border-radius: 7px; border: 1px solid var(--line-strong); background: var(--surface);
}

/* editor */
.editor {
  position: relative; flex: 1 1 auto; min-height: 14rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
}
.editor:focus-within { border-color: var(--green); }
.ed-scroll { position: absolute; inset: 0; overflow: auto; }
.ed-inner { display: grid; grid-template-columns: 3rem max-content; min-width: 100%; min-height: 100%; padding: 10px 0; }
.ed-gutter {
  position: sticky; left: 0; z-index: 2;
  font: 13px/var(--lh) var(--font-code); color: var(--ink-3); text-align: right;
  font-variant-numeric: tabular-nums; background: var(--surface); padding-right: 10px; user-select: none;
  min-height: 100%;
}
.ed-gutter span { display: block; }
.ed-code { position: relative; min-width: 100%; }
.ed-hl, .ed-input {
  margin: 0; padding: 0 20px 0 6px; border: 0;
  font: 14px/var(--lh) var(--font-code); tab-size: 2; white-space: pre; letter-spacing: 0;
}
.ed-hl { color: var(--ink); pointer-events: none; min-height: 100%; }
.ed-input {
  position: absolute; inset: 0; width: 100%; height: 100%; resize: none; overflow: hidden;
  background: transparent; color: transparent; caret-color: var(--ink); outline: none; z-index: 1;
}
.ed-input:focus-visible { box-shadow: none; }
.ed-band, .ed-err-row {
  position: absolute; left: 0; right: 0; height: var(--lh);
  top: calc(var(--line) * var(--lh));
}
.ed-band { background: var(--plastic-2); box-shadow: inset 3px 0 0 var(--turtle); transition: top 90ms linear; }
.ed-err-row { background: var(--danger-bg); }
.ed-err-mark {
  position: absolute; z-index: 1; pointer-events: none;
  top: calc(var(--line) * var(--lh)); height: var(--lh);
  left: calc(6px + var(--col) * 1ch); width: calc(var(--len) * 1ch);
  font: 14px/var(--lh) var(--font-code);
  border-bottom: 2px solid var(--danger);
}
.ed-bubble {
  position: absolute; z-index: 3; pointer-events: none;
  top: calc((var(--line) + 1) * var(--lh) + 3px);
  left: max(4px, calc(var(--col) * 1ch - 8px));
  width: max-content; max-width: min(30rem, 80vw); white-space: normal;
  font: 13px/1.45 var(--font-ui); padding: 7px 10px; border-radius: 8px;
  background: var(--danger); color: #fff; box-shadow: var(--shadow);
}
:root[data-theme="dark"] .ed-bubble { color: #2a0b08; }
.ed-bubble::before {
  content: ""; position: absolute; top: -5px; left: 12px; width: 10px; height: 10px;
  background: inherit; transform: rotate(45deg); border-radius: 2px;
}
.ed-bubble strong { font-weight: 700; }
.t-command { color: var(--t-command); font-weight: 600; }
.t-keyword { color: var(--t-keyword); font-weight: 600; }
.t-proc { color: var(--t-proc); }
.t-name { color: var(--t-name); }
.t-value { color: var(--t-proc); font-style: italic; }
.t-number { color: var(--t-number); }
.t-string { color: var(--t-string); }
.t-string::before {
  content: ""; display: inline-block; width: 0.7em; height: 0.7em; margin-right: 0.25em;
  border-radius: 3px; background: var(--swatch); vertical-align: -0.04em; box-shadow: inset 0 0 0 1px rgba(0,0,0,.15);
  margin-left: -0.95em;
}
.t-comment { color: var(--t-comment); font-style: italic; }
.t-bracket { color: var(--t-bracket); font-weight: 700; }
.t-paren, .t-op { color: var(--t-bracket); }
.t-bad { color: var(--danger); }

/* transport */
.transport { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.transport .btn { min-width: 0; }
.studio[data-status="running"] #run-btn { background: var(--green-strong); }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--ink-2); font-weight: 550; }
input[type="range"] { accent-color: var(--green); width: 110px; height: 28px; }
.status {
  margin: 0; min-height: 1.5em; font-size: 13.5px; color: var(--ink-2); font-variant-numeric: tabular-nums;
}
.studio[data-status="error"] .status { color: var(--danger); font-weight: 550; }
.shortcuts { font-size: 13px; color: var(--ink-2); }
.shortcuts summary { cursor: pointer; font-weight: 600; width: max-content; border-radius: 6px; padding: 2px 4px; margin-left: -4px; }
.shortcuts dl { display: grid; gap: 6px; margin: 10px 0 6px; }
.shortcuts dl div { display: grid; grid-template-columns: minmax(11rem, auto) 1fr; gap: 10px; align-items: baseline; }
.shortcuts dt, .shortcuts dd { margin: 0; }
.shortcuts p { margin: 4px 0 0; }

/* view */
.pane-view { position: relative; min-width: 0; min-height: 0; background: var(--canvas); }
.view-stage { position: absolute; inset: 0; }
.view-stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; }
.view-stage canvas.grabbing { cursor: grabbing; }
.view-stage canvas:focus-visible { box-shadow: inset 0 0 0 2px var(--green); border-radius: 0; }
.view-tools {
  position: absolute; right: 12px; bottom: 12px; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 2px;
  padding: 4px; border-radius: 12px; background: var(--surface); box-shadow: var(--shadow);
  max-width: calc(100% - 24px);
}
.tool-sep { width: 1px; align-self: stretch; margin: 6px 3px; background: var(--line); }
.view-stage[data-flat="true"] .only-3d, .view-stage[data-mode="3d"]:not([data-flat="true"]) .only-2d { display: none; }
.readout {
  position: absolute; left: 34px; bottom: 14px; pointer-events: none;
  font: 12px/1.3 var(--font-code); color: var(--ruler-ink); white-space: pre; font-variant-numeric: tabular-nums;
  padding: 5px 8px; border-radius: 7px; background: color-mix(in srgb, var(--canvas) 82%, transparent);
  max-width: calc(100% - 300px); overflow: hidden; text-overflow: ellipsis;
}
.view-stage[data-flat="false"] .readout { left: 12px; }
.view-note {
  position: absolute; left: 34px; right: 12px; top: 34px; z-index: 2; max-width: 40rem;
  padding: 10px 12px; border-radius: var(--radius); font-size: 13.5px;
  background: var(--surface); color: var(--ink); box-shadow: var(--shadow);
}

/* challenge task panel */
.task {
  display: grid; gap: 8px; padding: 14px; border-radius: var(--radius);
  background: var(--plastic); border: 1px solid var(--plastic-2);
}
.task-head { display: flex; justify-content: space-between; align-items: center; }
.task .back { display: inline-flex; align-items: center; gap: 2px; font-size: 13px; font-weight: 600; text-decoration: none; }
.task .back .i { width: 16px; height: 16px; }
.mode-tag { font-size: 12px; font-weight: 650; color: var(--green-ink); }
.task h1 { margin: 2px 0 0; font-size: 20px; line-height: 1.25; letter-spacing: -0.01em; }
.task p { margin: 0; }
.hint summary { cursor: pointer; font-weight: 600; color: var(--green-ink); width: max-content; font-size: 14px; border-radius: 6px; }
.hint p { margin-top: 6px; color: var(--ink-2); }
.task-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.verdict { margin: 0; font-size: 14px; flex: 1 1 14rem; }
.verdict.pass { color: var(--green-ink); font-weight: 600; }
.verdict.fail { color: var(--danger); font-weight: 550; }

/* ---------- pages ---------- */

.page { width: 100%; max-width: 74rem; margin: 0 auto; padding: 36px 24px 72px; }
.page-head { margin-bottom: 28px; }
.page-head h1 { margin: 0 0 8px; font-size: clamp(26px, 3.2vw, 34px); line-height: 1.15; letter-spacing: -0.02em; text-wrap: balance; }
.lede { margin: 0; max-width: 62ch; color: var(--ink-2); font-size: 16px; }
.group-h { font-size: 15px; font-weight: 650; color: var(--ink-2); margin: 32px 0 12px; }
.cells {
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); gap: 14px;
}
.cell {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--surface); border-radius: 12px; box-shadow: var(--shadow);
}
.cell .thumb { width: 100%; aspect-ratio: 4 / 3; display: block; border-bottom: 1px solid var(--line); }
.cell-body { display: flex; flex-direction: column; gap: 4px; padding: 12px 14px 14px; flex: 1; }
.cell-body h3 { margin: 0; font-size: 16px; letter-spacing: -0.005em; }
.cell-body h3 a { color: var(--ink); text-decoration: none; }
.cell-body h3 a::after { content: ""; position: absolute; inset: 0; }
.cell-body h3 a:hover { color: var(--green-ink); }
.cell-body p { margin: 0; color: var(--ink-2); font-size: 14px; }
.cell-action { margin-top: auto; align-self: flex-start; margin-top: 10px; }
#ch-list .cell { position: relative; }
#ch-list .cell:focus-within { box-shadow: var(--shadow), var(--focus); }
#ch-list .cell-body h3 a:focus-visible { box-shadow: none; }
.cell-meta { margin-top: auto; padding-top: 8px; display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 600; color: var(--ink-3); }
.cell.solved .cell-meta { color: var(--green-ink); }
.cell-meta .i { width: 16px; height: 16px; stroke-width: 2.4; }

/* reference (Read surface inside the app) */
.page-read { max-width: 60rem; }
.toc { display: flex; flex-wrap: wrap; gap: 4px 6px; margin-top: 18px; }
.toc a {
  font-size: 14px; font-weight: 550; padding: 5px 10px; border-radius: 8px; text-decoration: none;
  background: var(--plastic); color: var(--green-ink);
}
.toc a:hover { background: var(--plastic-2); }
.ref-section { margin-top: 44px; scroll-margin-top: 72px; }
.ref-section h2 { font-size: 22px; letter-spacing: -0.01em; margin: 0 0 12px; outline: none; }
.ref-section > p, .ref-section li { max-width: 70ch; }
.ref-section li { margin-bottom: 6px; }
.ref-list { margin: 0; display: grid; gap: 0; border-top: 1px solid var(--line); }
.ref-entry { display: grid; grid-template-columns: minmax(12rem, 16rem) 1fr; gap: 8px 24px; padding: 16px 0; border-bottom: 1px solid var(--line); }
.ref-entry dt { display: flex; flex-direction: column; gap: 4px; }
.ref-entry dt .cmd { font-weight: 700; color: var(--t-command); font-size: 15px; }
.ref-en { font: 13px var(--font-code); color: var(--ink-3); }
.ref-entry dd { margin: 0; }
.ref-entry dd p { margin: 0 0 6px; max-width: 64ch; }
.ref-arg { font-size: 13.5px; color: var(--ink-2); }
.ref-example { display: flex; align-items: flex-start; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
pre.code {
  margin: 0; padding: 9px 12px; border-radius: 8px; background: var(--sunken);
  font-size: 13.5px; line-height: 1.55; overflow-x: auto; flex: 0 1 auto; max-width: 100%;
}
.limits { border-collapse: collapse; width: 100%; max-width: 46rem; font-size: 14px; }
.limits caption { text-align: left; color: var(--ink-2); padding-bottom: 8px; }
.limits th, .limits td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.limits th { font-weight: 500; }
.limits td { font-variant-numeric: tabular-nums; font-weight: 650; white-space: nowrap; }

/* toast */
.toast {
  position: fixed; left: 50%; bottom: max(16px, env(safe-area-inset-bottom)); z-index: 40;
  transform: translateX(-50%); display: flex; align-items: center; gap: 10px;
  max-width: calc(100vw - 24px); padding: 8px 8px 8px 16px; border-radius: 12px;
  background: var(--ink); color: var(--paper); box-shadow: var(--shadow); font-size: 14px;
  animation: toast-in 320ms var(--ease);
}
.toast .btn { background: transparent; color: inherit; border-color: color-mix(in srgb, var(--paper) 40%, transparent); }
.toast .btn-icon { color: inherit; }
.toast .btn-icon:hover, .toast .btn:hover { background: color-mix(in srgb, var(--paper) 14%, transparent); }
@keyframes toast-in { from { opacity: 0; transform: translate(-50%, 8px); filter: blur(3px); } }

/* ---------- small screens ---------- */

@media (max-width: 880px) {
  .studio { display: flex; flex-direction: column; height: auto; }
  .pane-view { order: -1; height: min(52vh, 32rem); min-height: 260px; flex: none; }
  .pane-code { border-right: 0; overflow: visible; padding: 12px; }
  .editor { flex: none; height: 46vh; min-height: 16rem; }
  .readout { display: none; }
  .view-note { left: 12px; }
}
@media (max-width: 600px) {
  .topbar { flex-wrap: wrap; gap: 6px 12px; padding-top: 6px; padding-bottom: 6px; }
  .mainnav { order: 3; width: 100%; margin: 0 -8px; }
  .mainnav a { padding: 6px 10px; }
  .transport .btn span { display: none; }
  .transport .btn { width: 44px; padding: 0; min-height: 44px; }
  .btn-icon { width: 44px; height: 44px; }
  .speed { margin-left: 0; flex: 1; }
  .speed input { flex: 1; }
  .page { padding: 24px 16px 56px; }
  .ref-entry { grid-template-columns: 1fr; }
  .shortcuts dl div { grid-template-columns: 1fr; gap: 2px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; }
}

