cd /work; bun add -d happy-dom@^15 2>&1 | tail -1; mkdir -p tests/dom; cat > tests/dom/app.test.ts <<'EOF'
import { beforeAll, describe, expect, test } from "bun:test";
import { boot, click, type App } from "./harness";

let app: App;
beforeAll(async () => { app = await boot(); });

describe("app: testing hook", () => {
  test("exposes version, run and open", () => {
    expect(typeof app.win.logomocja.version).toBe("string");
    expect(app.win.logomocja.run("np 10", "2d").segments.length).toBe(1);
  });
  test("open loads the source into the editor, runs it to the end and reports the result", async () => {
    const res = await app.win.logomocja.open("powtorz 4 [np 50 pw 90]", "2d");
    expect(res.error).toBeNull();
    expect(res.segments.length).toBe(4);
    expect(app.$<HTMLTextAreaElement>(".ed-input").value).toBe("powtorz 4 [np 50 pw 90]");
  });
  test("open reports a parse error with nothing drawn and marks the editor", async () => {
    const res = await app.win.logomocja.open("np 10\nnp )", "2d");
    expect(res).toEqual({ segments: [], error: expect.objectContaining({ line: 2, column: 4 }) });
    expect(app.$(".ed-bubble").hidden).toBe(false);
    expect(app.$(".ed-bubble").textContent).toContain("Wiersz 2, kolumna 4");
  });
  test("open agrees with run for every mode and repeated calls", async () => {
    for (const [src, mode] of [["gora 90 np 10", "3d"], ["np 1 / 0", "2d"], ["np 5", "2d"]] as const) {
      const a = await app.win.logomocja.open(src, mode);
      expect(a).toEqual(app.win.logomocja.run(src, mode));
    }
  });
});
EOF
bun test tests/dom 2>&1 | tail -3

