cd /work; cat > tests/dom/harness.ts <<'EOF'
/**
 * Boots the real index.html + src/main.ts inside happy-dom. Only the canvas
 * raster context is stubbed (happy-dom has no rasteriser) and WebGL is absent,
 * so 3D runs in its documented "no WebGL" fallback.
 */
import { Window } from "happy-dom";
import { readFileSync } from "node:fs";

export interface App {
  win: Window & typeof globalThis & { logomocja: any };
  $<T extends HTMLElement = HTMLElement>(sel: string): T;
  storage: Storage;
}

const ctx2d = () =>
  new Proxy({}, {
    get: (_t, k) => (k === "measureText" ? () => ({ width: 10 }) : k === "canvas" ? undefined : () => {}),
    set: () => true,
  });

export async function boot(opts: { hash?: string; storage?: Record<string, string> } = {}): Promise<App> {
  const win = new Window({ url: "http://localhost/Logomocja/builds/x/" + (opts.hash ?? ""), width: 1280, height: 800 }) as any;
  const html = readFileSync(new URL("../../index.html", import.meta.url), "utf8");
  win.document.write(html.replace(/<script[\s\S]*?<\/script>/g, ""));
  for (const [k, v] of Object.entries(opts.storage ?? {})) win.localStorage.setItem(k, v);
  win.HTMLCanvasElement.prototype.getContext = function (type: string) { return type === "2d" ? ctx2d() : null; };
  win.HTMLCanvasElement.prototype.toBlob = function (cb: (b: Blob) => void) { cb(new Blob(["png"], { type: "image/png" })); };
  win.requestAnimationFrame = (f: (t: number) => void) => setTimeout(() => f(performance.now()), 0) as unknown as number;
  win.cancelAnimationFrame = (id: number) => clearTimeout(id);
  const g = globalThis as any;
  for (const k of ["window", "document", "localStorage", "location", "history", "navigator", "HTMLElement", "HTMLCanvasElement",
    "HTMLInputElement", "HTMLButtonElement", "HTMLAnchorElement", "HTMLTextAreaElement", "Node", "Event", "KeyboardEvent", "Blob",
    "ResizeObserver", "matchMedia", "getComputedStyle", "requestAnimationFrame", "cancelAnimationFrame", "devicePixelRatio", "URL"]) {
    if (k === "URL") { g.URL.createObjectURL = () => "blob:x"; g.URL.revokeObjectURL = () => {}; continue; }
    g[k] = win[k];
  }
  g.window = win;
  // fresh module graph per boot
  await import("../../src/main.ts?" + Math.random());
  await settle();
  return { win, $: (sel: string) => win.document.querySelector(sel), storage: win.localStorage };
}

/** waits for queued frames and promises */
export const settle = async (ms = 30) => { await new Promise((r) => setTimeout(r, ms)); };

export async function click(el: HTMLElement) {
  el.click();
  await settle();
}

export async function type(app: App, text: string) {
  const ta = app.$<HTMLTextAreaElement>(".ed-input");
  ta.value = text;
  ta.dispatchEvent(new app.win.Event("input", { bubbles: true }) as unknown as Event);
  await settle();
}
EOF
