cd /work; cat > tests/dom/controls.test.ts <<'EOF'
import { beforeAll, describe, expect, test } from "bun:test";
import { boot, click, settle, type, type App } from "./harness";

let app: App;
beforeAll(async () => { app = await boot(); });

const status = () => app.$("#status").textContent ?? "";

describe("transport controls", () => {
  test("Krok executes one command at a time and highlights the next line", async () => {
    await type(app, "np 10\npw 90\nnp 20");
    await click(app.$("#reset-btn"));
    await click(app.$("#step-btn"));
    expect(app.$(".ed-band").hidden).toBe(false);
    expect(app.$(".ed-band").style.getPropertyValue("--line")).toBe("1");
    expect(status()).toContain("wiersz 2");
    await click(app.$("#step-btn"));
    await click(app.$("#step-btn"));
    expect(status()).toContain("Gotowe. 2 odcinki");
    expect(app.$(".ed-band").hidden).toBe(true);
  });
  test("Uruchom animates; Pauza holds; Wznów finishes", async () => {
    const speed = app.$<HTMLInputElement>("#speed");
    speed.value = "1";
    speed.dispatchEvent(new app.win.Event("input") as unknown as Event);
    await type(app, "powtorz 50 [np 1]");
    await click(app.$("#run-btn"));
    expect(app.$("#studio").dataset.status).toBe("running");
    await click(app.$("#pause-btn"));
    expect(app.$("#studio").dataset.status).toBe("paused");
    expect(app.$("#pause-btn").textContent).toContain("Wznów");
    speed.value = "10";
    speed.dispatchEvent(new app.win.Event("input") as unknown as Event);
    await click(app.$("#pause-btn"));
    await settle(60);
    expect(status()).toContain("Gotowe. 50 odcinków");
  });
  test("keyboard shortcuts drive the same controls", async () => {
    await type(app, "np 5");
    const key = (init: KeyboardEventInit) => app.win.document.dispatchEvent(new app.win.KeyboardEvent("keydown", { ...init, bubbles: true }) as unknown as Event);
    key({ key: "Enter", ctrlKey: true });
    await settle(60);
    expect(status()).toContain("Gotowe. 1 odcinek");
    key({ key: "Backspace", ctrlKey: true, shiftKey: true });
    await settle();
    expect(app.$("#studio").dataset.status).toBe("idle");
    key({ key: "Enter", ctrlKey: true, shiftKey: true });
    await settle();
    expect(app.$("#studio").dataset.status).toBe("done");
  });
  test("editing during a run stops it and says the drawing is stale", async () => {
    const speed = app.$<HTMLInputElement>("#speed");
    speed.value = "1";
    speed.dispatchEvent(new app.win.Event("input") as unknown as Event);
    await type(app, "powtorz 50 [np 1]");
    await click(app.$("#run-btn"));
    await type(app, "powtorz 50 [np 2]");
    expect(app.$("#studio").dataset.status).toBe("stale");
    expect(status()).toContain("Program zmieniony");
  });
  test("a run-time error is marked in the editor and keeps the drawing", async () => {
    app.$<HTMLInputElement>("#speed").value = "10";
