import { describe, expect, test } from "bun:test";
import { boot, click, settle, type } from "./harness";
import { permalinkHash } from "../../src/share";
import { EXAMPLES } from "../../src/examples";

const editorText = (app: Awaited<ReturnType<typeof boot>>) => app.$<HTMLTextAreaElement>(".ed-input").value;

describe("product flows", () => {
  test("the draft survives a reload", async () => {
    const a = await boot();
    await type(a, "np 77 ; mój");
    const store: Record<string, string> = {};
    for (let k = 0; k < a.storage.length; k++) { const key = a.storage.key(k)!; store[key] = a.storage.getItem(key)!; }
    const b = await boot({ storage: store });
    expect(editorText(b)).toBe("np 77 ; mój");
  });
  test("opening an example from Przykłady keeps the draft and offers to restore it", async () => {
    const app = await boot();
    await type(app, "np 33 ; moje");
    app.win.location.hash = "#/przyklady";
    await settle();
    expect(app.$("#przyklady").hidden).toBe(false);
    const btn = app.$(`#ex-3d button[aria-label="Otwórz przykład Helisa w studiu"]`);
    await click(btn);
    await settle(60);
    expect(app.$("#studio").hidden).toBe(false);
    expect(editorText(app)).toBe(EXAMPLES.find((e) => e.id === "helisa")!.source);
    expect(app.$('#mode-switch [data-mode="3d"]').getAttribute("aria-checked")).toBe("true");
    expect(app.$("#gl-note").hidden).toBe(false);
    expect(app.$("#gl-note").textContent).toContain("WebGL");
    // the draft was the 2D one; switch back and the 2D draft is still there
    await click(app.$('#mode-switch [data-mode="2d"]'));
    await settle(60);
    expect(editorText(app)).toBe("np 33 ; moje");
  });
  test("replacing a draft in the same mode shows a restore action that works", async () => {
    const app = await boot();
    await type(app, "np 44 ; moje");
    app.win.location.hash = "#/przyklady";
    await settle();
    await click(app.$(`#ex-2d button[aria-label="Otwórz przykład Gwiazda w studiu"]`));
    await settle(60);
    expect(app.$("#toast").hidden).toBe(false);
    const restore = [...app.$("#toast").querySelectorAll("button")].find((b) => b.textContent === "Przywróć szkic")!;
    await click(restore as unknown as HTMLElement);
    expect(editorText(app)).toBe("np 44 ; moje");
  });
  test("a permalink opens and runs the program in its mode", async () => {
    const app = await boot({ hash: permalinkHash("gora 90 np 25", "3d") });
    await settle(80);
    expect(editorText(app)).toBe("gora 90 np 25");
    expect(app.$("#status").textContent).toContain("Gotowe. 1 odcinek");
    expect(app.win.location.hash).toBe("#/");
  });
  test("the link button produces a permalink for the current program under the base path", async () => {
    const app = await boot();
    await type(app, "np 12");
    await click(app.$("#link-btn"));
    const url = app.$<HTMLInputElement>("#share-url").value;
    expect(url).toBe("http://localhost/Logomocja/builds/x/" + permalinkHash("np 12", "2d"));
  });
  test("a challenge passes and the solved count persists", async () => {
    const app = await boot();
    app.win.location.hash = "#/zadania/szesciokat";
    await settle(60);
    expect(app.$("#task").hidden).toBe(false);
    await type(app, "powtorz 6 [np 60 pw 60]");
    await click(app.$("#check-btn"));
    expect(app.$("#verdict").textContent).toContain("Zaliczone");
    expect(app.$("#solved-count").textContent).toBe("1/7");
    const store: Record<string, string> = {};
    for (let k = 0; k < app.storage.length; k++) { const key = app.storage.key(k)!; store[key] = app.storage.getItem(key)!; }
    const again = await boot({ storage: store, hash: "#/zadania" });
    expect(again.$("#solved-count").textContent).toBe("1/7");
  });
  test("a wrong challenge answer fails with a reason", async () => {
    const app = await boot({ hash: "#/zadania/trojkat" });
    await settle(60);
    await type(app, "np 100");
    await click(app.$("#check-btn"));
    expect(app.$("#verdict").textContent).toMatch(/^Jeszcze nie\. /);
  });
  test("the reference page documents every command", async () => {
    const app = await boot({ hash: "#/sciaga" });
    const text = app.$("#sciaga").textContent!;
    for (const w of ["naprzód", "wstecz", "prawo", "lewo", "podnieś", "opuść", "kolor", "grubość", "powtórz", "niech", "jeśli", "jeżeli", "stop", "dom", "czyść", "góra", "dół", "przechylprawo", "przechyllewo", "nrpowt", "oto", "już", "50 000"])
      expect(text).toContain(w);
  });
  test("theme toggle cycles and is remembered", async () => {
    const app = await boot();
    await click(app.$("#theme-btn"));
    expect(app.win.document.documentElement.dataset.theme).toBe("light");
    await click(app.$("#theme-btn"));
    expect(app.win.document.documentElement.dataset.theme).toBe("dark");
    expect(app.storage.getItem("logomocja:v1:theme")).toBe("dark");
  });
});
EOF
